(window.APUSH_TOPICS=window.APUSH_TOPICS||{})[6]=[{"id": "p6-001", "period": 6, "topic_en": "Vertical integration", "topic_zh": "纵向一体化", "year": null, "year_text": "1880s", "who": ["Andrew Carnegie", "Gustavus Swift", "John D. Rockefeller"], "who_zh": ["安德鲁·卡内基", "古斯塔夫斯·斯威夫特", "约翰·D·洛克菲勒"], "what_en": "Vertically integrated corporations controlled production from the harvesting of raw materials through the sale of finished products. Carnegie built such a steel empire, Swift did the same in meatpacking, and Rockefeller controlled oil all the way from the oil well to the kerosene lamp.", "what_zh": "纵向一体化的公司从原材料采集到成品销售全程控制生产。卡内基建立了钢铁帝国，斯威夫特在肉类加工中同样如此，洛克菲勒则控制了从油井到煤油灯的石油全链条。", "cause_en": "Railroad networks, new technologies like the Bessemer converter, and Republican tariffs made coordinated large-scale production profitable.", "cause_zh": "铁路网、贝塞麦转炉等新技术以及共和党的保护性关税，使大规模协同生产有利可图。", "sig_en": "Vertical integration let managers control costs and build near-monopolies, making the corporation the dominant business form of industrial America.", "sig_zh": "纵向一体化让经理人控制成本、建立近乎垄断的企业，使公司制成为工业化美国的主导商业形态。", "exp_en": "Vertical integration was the organizational breakthrough that let a single firm dominate an entire industry chain, lowering costs but concentrating economic power.", "exp_zh": "纵向一体化是组织上的突破，让一家企业主导整条产业链：成本下降，但经济权力高度集中。", "page": 547, "topic_es": "Integración vertical", "what_es": "Las corporaciones integradas verticalmente controlaban la producción desde la recolección de materias primas hasta la venta de productos terminados. Carnegie construyó así un imperio del acero, Swift hizo lo mismo en la industria cárnica y Rockefeller controló el petróleo desde el pozo hasta la lámpara de queroseno.", "cause_es": "Las redes ferroviarias, nuevas tecnologías como el convertidor Bessemer y los aranceles republicanos hicieron rentable la producción coordinada a gran escala.", "sig_es": "La integración vertical permitió a los gerentes controlar costos y construir casi monopolios, convirtiendo a la corporación en la forma empresarial dominante de la América industrial.", "exp_es": "La integración vertical fue el avance organizativo que permitió a una sola empresa dominar toda una cadena industrial, reduciendo costos pero concentrando el poder económico.", "who_es": ["Andrew Carnegie", "Gustavus Swift", "John D. Rockefeller"], "img": {"file": "img:f1_3574", "credit": "图源：Henretta《America's History》第8版 p.547"}}, {"id": "p6-002", "period": 6, "topic_en": "Standard Oil trust (horizontal integration)", "topic_zh": "标准石油托拉斯（横向一体化）", "year": 1882, "year_text": "1882", "who": ["John D. Rockefeller"], "who_zh": ["约翰·D·洛克菲勒"], "what_en": "After driving competitors to the brink through predatory pricing, Rockefeller invited them to merge into his conglomerate; in 1882 his lawyers created the trust, a board of trustees holding the stock of combined firms as a single entity. Standard Oil came to control 95 percent of the nation's oil refining capacity.", "what_zh": "洛克菲勒用掠夺性定价把竞争对手逼到破产边缘，再邀其并入自己的集团；1882年他的律师创造了托拉斯这一法律形式——由受托人董事会持有合并企业股票、作为单一实体经营。标准石油最终控制了全国95%的炼油产能。", "cause_en": "Secret railroad rebates and predatory pricing gave Standard Oil an unbeatable advantage, leaving rivals no choice but to merge.", "cause_zh": "铁路的秘密回扣和掠夺性定价让标准石油获得不可战胜的优势，对手别无选择只能合并。", "sig_en": "The trust became the model for giant monopolies and provoked the antitrust movement that produced the Sherman Antitrust Act.", "sig_zh": "托拉斯成为巨型垄断的样板，也激起了反垄断运动，最终促成《谢尔曼反托拉斯法》。", "exp_en": "Rockefeller combined horizontal integration (absorbing rivals) with vertical integration (controlling wells, pipelines, distribution) — the fullest expression of Gilded Age monopoly capitalism.", "exp_zh": "洛克菲勒把横向一体化（吞并对手）与纵向一体化（控制油井、管道、分销）结合起来，是镀金时代垄断资本主义最完整的体现。", "page": 548, "topic_es": "El trust de Standard Oil (integración horizontal)", "what_es": "Tras llevar a sus competidores al borde de la ruina con precios predatorios, Rockefeller los invitó a fusionarse en su conglomerado; en 1882 sus abogados crearon el trust, una junta de fiduciarios que poseía las acciones de las empresas combinadas como una sola entidad. Standard Oil llegó a controlar el 95 por ciento de la capacidad nacional de refinación de petróleo.", "cause_es": "Los reembolsos ferroviarios secretos y los precios predatorios dieron a Standard Oil una ventaja imbatible, sin dejar a sus rivales otra opción que fusionarse.", "sig_es": "El trust se convirtió en el modelo de los grandes monopolios y provocó el movimiento antimonopolista que produjo la Sherman Antitrust Act.", "exp_es": "Rockefeller combinó la integración horizontal (absorber rivales) con la integración vertical (controlar pozos, oleoductos y distribución): la expresión más completa del capitalismo monopolista de la Edad Dorada.", "who_es": ["John D. Rockefeller"]}, {"id": "p6-003", "period": 6, "topic_en": "Scientific management (Taylorism)", "topic_zh": "科学管理（泰勒制）", "year": null, "year_text": "early 1900s", "who": ["Frederick W. Taylor"], "who_zh": ["弗雷德里克·W·泰勒"], "what_en": "Metal-cutting expert Frederick W. Taylor urged employers to eliminate all brain work from manual labor, hiring experts to set shop-floor rules and timing each task with a stopwatch. Workers were required to do what they were told promptly and without asking questions or making suggestions.", "what_zh": "金属切削专家泰勒主张把脑力劳动从体力劳动中彻底剥离：雇专家制定车间规则、用秒表测定每道工序时间；工人必须迅速服从、不许提问或提建议。", "cause_en": "Managers wanted to cut costs, control workers, and raise output in mass-production industries.", "cause_zh": "经理人想在批量生产行业中削减成本、控制工人、提高产量。", "sig_en": "Scientific management became the emblem of deskilled wage work, though workers stubbornly resisted it and implementation proved expensive.", "sig_zh": "科学管理成为去技能化雇佣劳动的象征，但工人顽强抵制，实施成本也很高。", "exp_en": "Taylorism treated workers as machines responding automatically to higher pay — efficient on paper, explosive in practice.", "exp_zh": "泰勒制把工人当作对高工资自动反应的机器——纸面上高效，实践中引爆冲突。", "page": 552, "src": {"text": "Workers must be required to do what they are told promptly and without asking questions or making suggestions.", "attr": "Frederick W. Taylor (as quoted in the text)"}, "topic_es": "Administración científica (taylorismo)", "what_es": "Frederick W. Taylor, experto en corte de metales, instó a los empleadores a eliminar todo trabajo intelectual del trabajo manual, contratando expertos para fijar las reglas del taller y cronometrando cada tarea. Se exigía a los obreros hacer lo que se les ordenaba con prontitud y sin hacer preguntas ni sugerencias.", "cause_es": "Los gerentes querían reducir costos, controlar a los obreros y aumentar la producción en las industrias de producción masiva.", "sig_es": "La administración científica se convirtió en el emblema del trabajo asalariado descualificado, aunque los obreros la resistieron con obstinación y su aplicación resultó costosa.", "exp_es": "El taylorismo trataba a los obreros como máquinas que respondían automáticamente a un salario mayor: eficiente sobre el papel, explosivo en la práctica.", "who_es": ["Frederick W. Taylor"], "img": {"file": "img:f1_3587", "credit": "图源：Henretta《America's History》第8版 p.552"}}, {"id": "p6-004", "period": 6, "topic_en": "Deskilling", "topic_zh": "去技能化", "year": null, "year_text": "1880s", "who": ["factory workers"], "who_zh": ["工厂工人"], "what_en": "Automatic machinery subdivided work until one man made just a particular part of a machine; such a worker cannot be master of a craft, but only master of a fragment. Employers could then pay unskilled workers less and replace them easily.", "what_zh": "自动机器把工作细分到一人只做机器的某一个零件；这样的工人成不了手艺大师，只能是碎片的大师。雇主于是可以付更低的工资、轻易替换工人。", "cause_en": "Employers adopted automatic machinery to increase output and cut labor costs, discovering it also helped them control workers.", "cause_zh": "雇主采用自动机器本为提高产量、削减成本，却发现它还能帮助控制工人。", "sig_en": "Deskilling displaced traditional craftsmen and expanded low-wage factory work, deepening the conflict between labor and capital.", "sig_zh": "去技能化挤掉了传统手艺人，扩大了低薪工厂劳动，加深了劳资冲突。", "exp_en": "Deskilling turned skilled artisans into interchangeable machine-tenders — the human cost behind mass production's cheap goods.", "exp_zh": "去技能化把熟练工匠变成可替换的机器看守——这就是批量生产廉价商品背后的人力代价。", "page": 551, "topic_es": "Descualificación del trabajo", "what_es": "La maquinaria automática subdividió el trabajo hasta que un hombre fabricaba solo una parte determinada de una máquina; ese obrero no puede ser maestro de un oficio, sino solo maestro de un fragmento. Los empleadores podían entonces pagar menos a obreros no calificados y reemplazarlos con facilidad.", "cause_es": "Los empleadores adoptaron la maquinaria automática para aumentar la producción y reducir los costos laborales, descubriendo que también les ayudaba a controlar a los obreros.", "sig_es": "La descualificación desplazó a los artesanos tradicionales y expandió el trabajo fabril mal pagado, profundizando el conflicto entre el trabajo y el capital.", "exp_es": "La descualificación convirtió a artesanos calificados en operarios intercambiables de máquinas: el costo humano detrás de las mercancías baratas de la producción masiva.", "who_es": ["trabajadores fabriles"], "img": {"file": "img:f1_3585", "credit": "图源：Henretta《America's History》第8版 p.551"}}, {"id": "p6-005", "period": 6, "topic_en": "Great Railroad Strike of 1877", "topic_zh": "1877年铁路大罢工", "year": 1877, "year_text": "1877", "who": ["railroad workers", "Barney Donahue"], "who_zh": ["铁路工人", "巴尼·多纳休"], "what_en": "Protesting steep wage cuts amid the depression that began in 1873, thousands of railroad workers walked off the job, halting rail travel and commerce. When Pennsylvania's governor sent state militia to break the strike, Pittsburgh crowds burned railroad property and overturned locomotives.", "what_zh": "为抗议1873年大萧条以来的大幅降薪，数千铁路工人罢工，铁路运输和商业陷入停顿。宾州州长派民兵镇压后，匹兹堡群众烧毁铁路财产、掀翻机车。", "cause_en": "Railroad companies cut wages sharply during the depression and tried to break workers' organizations and mutual-aid fellowship.", "cause_zh": "铁路公司在大萧条中大幅降薪，并试图打碎工人的组织和互助团体。", "sig_en": "The strike first brought the problem of industrial labor into national consciousness and revealed the scale of labor-capital conflict in industrial America.", "sig_zh": "这次罢工首次让工业劳工问题进入全国视野，揭示了工业化美国劳资冲突的规模。", "exp_en": "The Great Railroad Strike was America's first nationwide labor upheaval — and the first time the state used military force to break a strike.", "exp_zh": "1877年铁路大罢工是美国第一次全国性劳工动荡，也是国家首次动用军事力量镇压罢工。", "page": 565, "topic_es": "Gran Huelga Ferroviaria de 1877", "what_es": "En protesta por los drásticos recortes salariales en medio de la depresión iniciada en 1873, miles de trabajadores ferroviarios abandonaron el trabajo, paralizando el transporte ferroviario y el comercio. Cuando el gobernador de Pensilvania envió la milicia estatal para romper la huelga, las multitudes de Pittsburgh quemaron propiedades del ferrocarril y volcaron locomotoras.", "cause_es": "Las compañías ferroviarias recortaron bruscamente los salarios durante la depresión e intentaron destruir las organizaciones obreras y su mutualismo.", "sig_es": "La huelga llevó por primera vez el problema del trabajo industrial a la conciencia nacional y reveló la magnitud del conflicto entre el trabajo y el capital en la América industrial.", "exp_es": "La Gran Huelga Ferroviaria fue la primera conmoción laboral de alcance nacional en Estados Unidos, y la primera vez que el Estado usó la fuerza militar para romper una huelga.", "who_es": ["trabajadores ferroviarios", "Barney Donahue"]}, {"id": "p6-006", "period": 6, "topic_en": "Knights of Labor", "topic_zh": "劳工骑士团", "year": 1869, "year_text": "1869 (founded)", "who": ["Terence Powderly", "Leonora Barry"], "who_zh": ["特伦斯·鲍德利", "利奥诺拉·巴里"], "what_en": "Founded in 1869 as a secret society of Philadelphia garment workers, the Knights sought a cooperative commonwealth of employee-owned shops, practiced open membership regardless of race, gender, or field (though excluding Chinese immigrants), and demanded workplace safety laws, an end to child labor, and public ownership of railroads and telegraphs.", "what_zh": "劳工骑士团1869年作为费城制衣工人的秘密会社成立，追求雇员所有的合作联邦；不分种族性别行业开放入会（但排斥华人）；要求工作场所安全法、禁止童工、铁路电报公有。", "cause_en": "Industrial exploitation convinced ordinary workers they needed control over the enterprises in which they worked, and only electoral action could deliver it.", "cause_zh": "工业剥削让普通工人相信必须掌控自己工作的企业，而这只有通过选举政治才能实现。", "sig_en": "The most important union of the late nineteenth century, the Knights collapsed after Haymarket hysteria drove skilled workers out of the order.", "sig_zh": "作为19世纪晚期最重要的工会，骑士团在干草市场事件后的反工会歇斯底里中瓦解。", "exp_en": "The Knights dreamed bigger than wages — a cooperative commonwealth — which is why both workers and employers found them threatening.", "exp_zh": "骑士团的梦想不止于工资，而是合作联邦——这正是工人和雇主都觉得它可怕的原因。", "page": 567, "why_term": "cooperative commonwealth", "why_term_q": "劳工骑士团追求的雇员所有制理想社会叫 ______。", "topic_es": "Caballeros del Trabajo", "what_es": "Fundados en 1869 como sociedad secreta de obreros de la confección de Filadelfia, los Caballeros buscaban una mancomunidad cooperativa de talleres propiedad de los empleados, practicaban la afiliación abierta sin distinción de raza, género u oficio (aunque excluían a los inmigrantes chinos) y exigían leyes de seguridad laboral, el fin del trabajo infantil y la propiedad pública de ferrocarriles y telégrafos.", "cause_es": "La explotación industrial convenció a los obreros comunes de que necesitaban controlar las empresas en las que trabajaban, y que solo la acción electoral podía lograrlo.", "sig_es": "El sindicato más importante de fines del siglo XIX, los Caballeros colapsaron después de que la histeria de Haymarket expulsara a los obreros calificados de la orden.", "exp_es": "Los Caballeros soñaban más allá del salario: una mancomunidad cooperativa, razón por la cual tanto obreros como empleadores los consideraban amenazantes.", "who_es": ["Terence Powderly", "Leonora Barry"], "why_term_q_es": "La sociedad ideal de propiedad de los empleados que buscaban los Caballeros del Trabajo se llamaba ______.", "img": {"file": "img:f1_3763", "credit": "图源：Henretta《America's History》第8版 p.567"}}, {"id": "p6-007", "period": 6, "topic_en": "Haymarket Square", "topic_zh": "干草市场事件", "year": 1886, "year_text": "May 4, 1886", "who": ["anarchists"], "who_zh": ["无政府主义者"], "what_en": "On May 4, 1886, Chicago anarchists, many of them German immigrants, called a protest meeting at Haymarket Square. When police tried to disperse the crowd, someone threw a bomb that killed several policemen; officers responded with gunfire. Eight anarchists were convicted of murder and conspiracy on the basis of their anti-government speeches, though the bomber's identity remains unknown.", "what_zh": "1886年5月4日，芝加哥无政府主义者（多为德裔移民）在干草市场广场集会抗议。警察驱散人群时有人投掷炸弹，数名警察死亡，警方开枪还击。八名无政府主义者仅凭反政府言论被判谋杀和阴谋罪，真凶至今不明。", "cause_en": "Chicago was a hotbed of anarchism, the revolutionary advocacy of a stateless society, and a protest had been called after a strike-related clash the day before.", "cause_zh": "芝加哥是无政府主义（主张无国家社会的革命思想）的温床，集会是为抗议前一天罢工冲突中的警察暴力。", "sig_en": "The violence profoundly damaged the American labor movement, as employers seized on anti-union hysteria to take the offensive.", "sig_zh": "这次暴力事件重创了美国劳工运动，雇主趁反工会歇斯底里发起反攻。", "exp_en": "Haymarket shows how a single bomb — thrown by persons unknown — could discredit an entire labor movement for a generation.", "exp_zh": "干草市场说明：一颗来历不明的炸弹，就能让整整一代劳工运动蒙羞。", "page": 568, "topic_es": "Haymarket Square", "what_es": "El 4 de mayo de 1886, anarquistas de Chicago, muchos de ellos inmigrantes alemanes, convocaron una manifestación de protesta en Haymarket Square. Cuando la policía intentó dispersar a la multitud, alguien lanzó una bomba que mató a varios policías; los agentes respondieron con disparos. Ocho anarquistas fueron condenados por asesinato y conspiración por sus discursos antigubernamentales, aunque la identidad del que lanzó la bomba sigue siendo desconocida.", "cause_es": "Chicago era un hervidero de anarquismo, la defensa revolucionaria de una sociedad sin Estado, y se había convocado una protesta tras un choque relacionado con una huelga el día anterior.", "sig_es": "La violencia dañó profundamente al movimiento obrero estadounidense, pues los empleadores aprovecharon la histeria antisindical para pasar a la ofensiva.", "exp_es": "Haymarket muestra cómo una sola bomba, lanzada por desconocidos, pudo desacreditar a todo un movimiento obrero durante una generación.", "who_es": ["anarquistas"], "img": {"file": "img:f1_3766", "credit": "图源：Henretta《America's History》第8版 p.568"}}, {"id": "p6-008", "period": 6, "topic_en": "Homestead lockout", "topic_zh": "霍姆斯特德封厂事件", "year": 1892, "year_text": "summer 1892", "who": ["Andrew Carnegie", "Henry Clay Frick"], "who_zh": ["安德鲁·卡内基", "亨利·克莱·弗里克"], "what_en": "Confident that new machinery let him replace skilled laborers, Carnegie withdrew to his Scottish estate in the summer of 1892, leaving his partner Henry Clay Frick in command. Frick locked out the workers, the state militia arrested labor leaders on riot and murder charges, most locked-out workers lost their jobs, and the union was dead.", "what_zh": "卡内基确信新机器可以替代熟练工人，1892年夏退居苏格兰庄园，把指挥权交给合伙人弗里克。弗里克封厂，州民兵以暴乱和谋杀罪逮捕工会领袖，大多数被封在外的工人丢了工作，工会覆灭。", "cause_en": "Carnegie decided collective bargaining was too expensive once new machinery, including the Bessemer converter, enabled him to replace skilled workers.", "cause_zh": "贝塞麦转炉等新机器让卡内基确信可以替代熟练工人，集体谈判变得太贵。", "sig_en": "Homestead showed industrialization was a controversial and often bloody process, with corporations backed by state force crushing unions.", "sig_zh": "霍姆斯特德表明工业化是充满争议、常常血腥的过程：有国家武力撑腰的公司碾碎了工会。", "exp_en": "Carnegie affirmed workers' right to organize — then let Frick do the dirty work of destroying the union.", "exp_zh": "卡内基口头上肯定工人组织权，转身却让弗里克去干摧毁工会的脏活。", "page": 544, "topic_es": "El cierre patronal de Homestead", "what_es": "Confiado en que la nueva maquinaria le permitía reemplazar a los obreros calificados, Carnegie se retiró a su finca escocesa en el verano de 1892, dejando a su socio Henry Clay Frick al mando. Frick cerró la planta a los obreros, la milicia estatal arrestó a líderes obreros por disturbios y asesinato, la mayoría de los excluidos perdió su empleo y el sindicato quedó muerto.", "cause_es": "Carnegie decidió que la negociación colectiva resultaba demasiado costosa una vez que la nueva maquinaria, incluido el convertidor Bessemer, le permitió reemplazar a los obreros calificados.", "sig_es": "Homestead demostró que la industrialización era un proceso polémico y a menudo sangriento, con las corporaciones respaldadas por la fuerza del Estado aplastando a los sindicatos.", "exp_es": "Carnegie afirmó el derecho de los obreros a organizarse, y luego dejó que Frick hiciera el trabajo sucio de destruir el sindicato.", "who_es": ["Andrew Carnegie", "Henry Clay Frick"]}, {"id": "p6-009", "period": 6, "topic_en": "American Federation of Labor", "topic_zh": "美国劳工联合会", "year": 1886, "year_text": "1886", "who": ["Samuel Gompers"], "who_zh": ["塞缪尔·龚帕斯"], "what_en": "After Haymarket drove skilled trade unionists out of the Knights of Labor, they formed the separate American Federation of Labor under Samuel Gompers, a Dutch-Jewish cigar maker. The AFL, made up of relatively skilled and well-paid workers, cared less about challenging the corporate order than about winning a larger share of its rewards, and enforced the closed shop.", "what_zh": "干草市场事件后，熟练技工脱离劳工骑士团，在雪茄工人龚帕斯领导下另组美国劳工联合会。成员多为技术较熟、收入较高的工人，不求挑战公司秩序，只求分得更大份额，并实行只雇工会会员的封闭工厂制。", "cause_en": "Trade unionists concluded the Knights relied too much on electoral politics and wanted narrowly focused unions that negotiated directly with employers.", "cause_zh": "技工们认为骑士团过于依赖选举政治，希望建立专注与雇主直接谈判的工会。", "sig_en": "The AFL's craft-union strategy survived while broad reform unions collapsed, shaping twentieth-century American labor's business-unionist character.", "sig_zh": "AFL的技工工会策略存活下来，而广泛改革型工会相继倒下，塑造了20世纪美国劳工的行业工会性格。", "exp_en": "Gompers traded the Knights' grand vision for bread-and-butter gains — and his union outlived them all.", "exp_zh": "龚帕斯用骑士团的宏大理想换面包黄油式的实际收益——他的工会活得比谁都长。", "page": 570, "topic_es": "Federación Americana del Trabajo", "what_es": "Después de que Haymarket expulsara a los sindicalistas de oficio de los Caballeros del Trabajo, estos formaron la separada Federación Americana del Trabajo bajo Samuel Gompers, un fabricante de cigarros judío holandés. La AFL, compuesta por obreros relativamente calificados y bien pagados, se preocupaba menos por desafiar el orden corporativo que por ganar una porción mayor de sus recompensas, e imponía el taller cerrado.", "cause_es": "Los sindicalistas concluyeron que los Caballeros dependían demasiado de la política electoral y quisieron sindicatos de enfoque estrecho que negociaran directamente con los empleadores.", "sig_es": "La estrategia de sindicalismo de oficio de la AFL sobrevivió mientras los sindicatos de reforma amplia colapsaban, moldeando el carácter sindicalista empresarial del trabajo estadounidense del siglo XX.", "exp_es": "Gompers cambió la gran visión de los Caballeros por ganancias concretas, y su sindicato los sobrevivió a todos.", "who_es": ["Samuel Gompers"], "img": {"file": "img:f1_3771", "credit": "图源：Henretta《America's History》第8版 p.570"}}, {"id": "p6-010", "period": 6, "topic_en": "Farmers' Alliance", "topic_zh": "农民同盟", "year": null, "year_text": "1870s–1880s", "who": ["farmers"], "who_zh": ["农民"], "what_en": "Founded in Texas during the depression of the 1870s, the Farmers' Alliance spread across the plains. Like the Knights of Labor, it sought political solutions to corporate exploitation of working people and reached a peak of activism just as the People's Party was being born.", "what_zh": "农民同盟在1870年代大萧条中创立于得克萨斯，蔓延到大平原。与劳工骑士团一样，它寻求用政治手段解决大公司对劳动人民的剥削，在人民党诞生前夕达到活动高峰。", "cause_en": "Farmers found their livelihoods at risk in the changing global economy as railroads, banks, and middlemen squeezed them.", "cause_zh": "在变化的全球经济中，铁路、银行和中间商挤压农民，农民的生计岌岌可危。", "sig_en": "The Alliance's grassroots activism flowed directly into the People's Party of 1892.", "sig_zh": "同盟的基层运动直接汇入了1892年的人民党。", "exp_en": "Farmers and workers discovered they faced the same enemy — the corporation — and the Alliance was their first great coalition.", "exp_zh": "农民和工人发现他们面对同一个敌人——大公司，农民同盟是他们的第一次大联合。", "page": 568, "topic_es": "Alianza de Agricultores", "what_es": "Fundada en Texas durante la depresión de la década de 1870, la Alianza de Agricultores se extendió por las llanuras. Como los Caballeros del Trabajo, buscó soluciones políticas a la explotación corporativa de los trabajadores y alcanzó su pico de activismo justo cuando nacía el Partido del Pueblo.", "cause_es": "Los agricultores vieron sus medios de vida en riesgo en la cambiante economía global, mientras ferrocarriles, bancos e intermediarios los exprimían.", "sig_es": "El activismo de base de la Alianza fluyó directamente hacia el Partido del Pueblo de 1892.", "exp_es": "Agricultores y obreros descubrieron que enfrentaban al mismo enemigo, la corporación, y la Alianza fue su primera gran coalición.", "who_es": ["agricultores"], "img": {"file": "img:f1_3766", "credit": "图源：Henretta《America's History》第8版 p.568"}}, {"id": "p6-011", "period": 6, "topic_en": "Granger laws", "topic_zh": "格兰杰法", "year": null, "year_text": "1870s–1880s", "who": ["Grangers"], "who_zh": ["格兰杰运动成员"], "what_en": "Under Greenback pressure, Midwestern states enacted economic regulatory measures known as Granger laws. By the early 1880s, twenty-nine states had created railroad commissions to supervise railroad rates and policies; others appointed commissions to regulate insurance and utility companies.", "what_zh": "在绿背党压力下，中西部各州通过了被称为格兰杰法的经济管制措施。到1880年代初，29个州设立铁路委员会监督铁路运价和政策，还有州管制保险和公用事业公司。", "cause_en": "Farmers protested discriminatory railroad rates and corporate power during the depression of the 1870s.", "cause_zh": "1870年代大萧条中，农民抗议铁路的歧视性运价和公司权力。", "sig_en": "Though not always effective, Granger laws were crucial starting points for regulating big business and pointed the way to the Interstate Commerce Act.", "sig_zh": "格兰杰法虽不总有效，却是管制大企业的关键起点，为《州际商务法》铺了路。", "exp_en": "The Grangers proved that even in the Gilded Age, voters could make the state regulate the railroad barons.", "exp_zh": "格兰杰运动证明：即便在镀金时代，选民也能迫使国家去管制铁路大亨。", "page": 566, "topic_es": "Leyes Granger", "what_es": "Bajo la presión de los greenbackers, los estados del Medio Oeste promulgaron medidas regulatorias económicas conocidas como leyes Granger. Para principios de la década de 1880, veintinueve estados habían creado comisiones ferroviarias para supervisar las tarifas y políticas de los ferrocarriles; otros nombraron comisiones para regular compañías de seguros y de servicios públicos.", "cause_es": "Los agricultores protestaron contra las tarifas ferroviarias discriminatorias y el poder corporativo durante la depresión de la década de 1870.", "sig_es": "Aunque no siempre efectivas, las leyes Granger fueron puntos de partida cruciales para regular a las grandes empresas y señalaron el camino hacia la Interstate Commerce Act.", "exp_es": "Los grangers demostraron que incluso en la Edad Dorada los votantes podían lograr que el Estado regulara a los barones del ferrocarril.", "who_es": ["Grangers"], "img": {"file": "img:f1_3761", "credit": "图源：Henretta《America's History》第8版 p.566"}}, {"id": "p6-012", "period": 6, "topic_en": "Greenback-Labor Party", "topic_zh": "绿背劳工党", "year": 1878, "year_text": "1878", "who": ["Greenbackers"], "who_zh": ["绿背党人"], "what_en": "Forged by Grangers, labor advocates, and workingmen's parties during the depression of the 1870s, the Greenback-Labor Party elected fifteen Congressmen in 1878. Its members subscribed to producerism, dismissing middlemen, bankers, lawyers, and investors as idlers who lived off the sweat of people who worked with their hands.", "what_zh": "绿背劳工党由格兰杰派、劳工鼓吹者和工人政党在1870年代大萧条中锻造，1878年选出15名国会议员。成员信奉生产者主义，蔑视中间商、银行家、律师和投资人是靠手工劳动者汗水生活的寄生虫。", "cause_en": "The depression of the 1870s and anger at tight-money policies and corporate power drove farmers and workers into politics.", "cause_zh": "1870年代大萧条以及对紧缩货币政策和公司权力的愤怒，把农民和工人推向政治。", "sig_en": "Though short-lived, the Greenback movement created the foundation for more sustained efforts to regulate big business.", "sig_zh": "绿背运动虽短命，却为后来更持久的管制大企业努力奠定了基础。", "exp_en": "Producerism divided America into makers and takers — and the Greenbackers knew exactly which side they were on.", "exp_zh": "生产者主义把美国分成创造者和寄生者——绿背党人很清楚自己站在哪一边。", "page": 565, "why_term": "producerism", "why_term_q": "绿背党人蔑视银行家等寄生虫、崇尚手工劳动者的思想叫 ______。", "topic_es": "Partido Greenback-Laborista", "what_es": "Forjado por grangers, defensores obreros y partidos de trabajadores durante la depresión de la década de 1870, el Partido Greenback-Laborista eligió quince congresistas en 1878. Sus miembros suscribían el producerismo, despreciando a intermediarios, banqueros, abogados e inversionistas como holgazanes que vivían del sudor de quienes trabajaban con las manos.", "cause_es": "La depresión de la década de 1870 y la ira contra las políticas de dinero escaso y el poder corporativo llevaron a agricultores y obreros a la política.", "sig_es": "Aunque efímero, el movimiento greenback creó la base para esfuerzos más sostenidos de regular a las grandes empresas.", "exp_es": "El producerismo dividía a Estados Unidos entre productores y parásitos, y los greenbackers sabían exactamente de qué lado estaban.", "who_es": ["Greenbackers"], "why_term_q_es": "La ideología de los greenbackers que despreciaba a los banqueros como parásitos y exaltaba a los trabajadores manuales se llamaba ______."}, {"id": "p6-013", "period": 6, "topic_en": "Progress and Poverty (Henry George)", "topic_zh": "《进步与贫困》（亨利·乔治）", "year": 1879, "year_text": "1879", "who": ["Henry George"], "who_zh": ["亨利·乔治"], "what_en": "In Progress and Poverty (1879), a best-seller for decades, Henry George warned that Americans were too optimistic about railroads and manufacturing. Industrialization, he wrote, was driving a wedge through society, lifting professionals and the middle class but pushing the working class into deskilled, dangerous, low-paid labor and permanent poverty.", "what_zh": "亨利·乔治的《进步与贫困》（1879）畅销数十年。他警告美国人对铁路和制造业过于乐观：工业化正在社会中打入楔子，抬高专业人士和中产阶级，却把工人阶级推入去技能化、危险、低薪的永久贫困。", "cause_en": "George watched industrial upheavals and concluded the new order meant lasting inequality, not shared prosperity.", "cause_zh": "乔治目睹工业剧变，认定新秩序意味着持久的不平等，而非共同繁荣。", "sig_en": "The book shaped radical critiques of industrial inequality and influenced agrarian-labor reformers for a generation.", "sig_zh": "该书塑造了一代人对工业不平等的激进批判，影响了农工改革者。", "exp_en": "George asked the Gilded Age's hardest question: why does poverty grow alongside progress?", "exp_zh": "乔治提出了镀金时代最难的问题：为什么贫困与进步同步增长？", "page": 565, "topic_es": "Progreso y miseria (Henry George)", "what_es": "En Progreso y miseria (1879), un éxito de ventas durante décadas, Henry George advirtió que los estadounidenses eran demasiado optimistas sobre los ferrocarriles y la manufactura. La industrialización, escribió, estaba abriendo una brecha en la sociedad, elevando a los profesionales y la clase media pero empujando a la clase obrera hacia un trabajo descualificado, peligroso y mal pagado y hacia la pobreza permanente.", "cause_es": "George observó las conmociones industriales y concluyó que el nuevo orden significaba desigualdad duradera, no prosperidad compartida.", "sig_es": "El libro moldeó las críticas radicales a la desigualdad industrial e influyó en los reformistas agrario-obreros durante una generación.", "exp_es": "George planteó la pregunta más difícil de la Edad Dorada: ¿por qué la pobreza crece junto al progreso?", "who_es": ["Henry George"]}, {"id": "p6-014", "period": 6, "topic_en": "Interstate Commerce Act", "topic_zh": "《州际商务法》", "year": 1887, "year_text": "1887", "who": ["U.S. Congress"], "who_zh": ["美国国会"], "what_en": "The Interstate Commerce Act of 1887 was the first major federal attempt to regulate corporations, creating federal oversight of railroad rates in response to farmer and labor protest.", "what_zh": "1887年《州际商务法》是联邦首次重大管制企业的尝试，回应农民和劳工的抗议，对铁路运价实行联邦监督。", "cause_en": "Pressure from the Knights of Labor, the Farmers' Alliance, and the Grangers forced Congress to confront railroad monopolies.", "cause_zh": "劳工骑士团、农民同盟和格兰杰运动的压力迫使国会直面铁路垄断。", "sig_en": "It marked the federal government's first major step into regulating big business, a precedent for the Sherman Act and Progressive Era regulation.", "sig_zh": "它标志着联邦政府管制大企业的第一步，为《谢尔曼法》和进步时代管制开了先例。", "exp_en": "The ICC was weak at birth — but its birth announced that railroads were no longer above the law.", "exp_zh": "州际商务委员会生来弱小，但它的诞生宣告铁路不再凌驾于法律之上。", "page": 569, "topic_es": "Interstate Commerce Act", "what_es": "La Interstate Commerce Act de 1887 fue el primer gran intento federal de regular a las corporaciones, creando la supervisión federal de las tarifas ferroviarias en respuesta a las protestas de agricultores y obreros.", "cause_es": "La presión de los Caballeros del Trabajo, la Alianza de Agricultores y los grangers obligó al Congreso a enfrentar los monopolios ferroviarios.", "sig_es": "Marcó el primer gran paso del gobierno federal hacia la regulación de las grandes empresas, un precedente para la Sherman Act y la regulación de la Era Progresista.", "exp_es": "La ICC nació débil, pero su nacimiento anunció que los ferrocarriles ya no estaban por encima de la ley.", "who_es": ["Congreso de EE. UU."]}, {"id": "p6-015", "period": 6, "topic_en": "Chinese Exclusion Act", "topic_zh": "《排华法案》", "year": 1882, "year_text": "1882", "who": ["Chinese laborers", "U.S. Congress"], "who_zh": ["华工", "美国国会"], "what_en": "Congress blocked all Chinese laborers from entering the United States in 1882. The act was later extended to other Asians, built the legal framework for broader exclusion, and turned the Chinese into America's first illegal immigrants — some evaded it as paper sons with forged family documents.", "what_zh": "国会1882年禁止所有华工入境。该法后来扩大到其他亚裔，建立了更广泛排斥的法律框架，并把华人变成美国第一批非法移民——有人以纸生子的伪造家庭文件规避。", "cause_en": "Virulent anti-Chinese prejudice and labor agitation led native-born workers and European immigrants to demand legal exclusion of Chinese workers.", "cause_zh": "恶毒的反华偏见和劳工煽动，使本土工人和欧洲移民要求以法律排斥华工。", "sig_en": "The act entrenched racial discrimination in immigration law for six decades (1882–1943) and pioneered the machinery of immigration restriction.", "sig_zh": "该法把种族歧视钉进移民法长达六十年（1882–1943），开创了移民限制的机器。", "exp_en": "Chinese exclusion was the first time the United States closed its gates by race — and built the bureaucracy to keep them closed.", "exp_zh": "排华是美国第一次以种族为由关闭国门——并建立官僚机器让大门持续关闭。", "page": 561, "topic_es": "Ley de Exclusión China", "what_es": "El Congreso bloqueó en 1882 la entrada a Estados Unidos de todos los trabajadores chinos. La ley se extendió después a otros asiáticos, construyó el marco legal para una exclusión más amplia y convirtió a los chinos en los primeros inmigrantes ilegales de Estados Unidos; algunos la evadieron como hijos de papel con documentos familiares falsificados.", "cause_es": "El virulento prejuicio antichino y la agitación obrera llevaron a trabajadores nativos e inmigrantes europeos a exigir la exclusión legal de los trabajadores chinos.", "sig_es": "La ley afianzó la discriminación racial en la ley de inmigración durante seis décadas (1882-1943) y fue pionera en la maquinaria de restricción migratoria.", "exp_es": "La exclusión china fue la primera vez que Estados Unidos cerró sus puertas por raza, y construyó la burocracia para mantenerlas cerradas.", "who_es": ["Trabajadores chinos", "Congreso de EE. UU."], "img": {"file": "img:f1_3744", "credit": "图源：Henretta《America's History》第8版 p.561"}}, {"id": "p6-016", "period": 6, "topic_en": "Plessy v. Ferguson", "topic_zh": "普莱西诉弗格森案", "year": 1896, "year_text": "1896", "who": ["U.S. Supreme Court"], "who_zh": ["美国最高法院"], "what_en": "In Plessy v. Ferguson (1896) the Supreme Court upheld segregation of schools and public facilities, legalizing the separate but equal doctrine.", "what_zh": "1896年普莱西诉弗格森案中，最高法院维持学校和公共设施的种族隔离，使隔离但平等原则合法化。", "cause_en": "Southern states imposed Jim Crow segregation after Reconstruction, and a legal challenge tested whether segregation violated the Constitution.", "cause_zh": "重建结束后南方各州推行吉姆·克劳隔离，一场诉讼考验隔离是否违宪。", "sig_en": "Plessy gave constitutional cover to segregation for more than half a century, until Brown v. Board of Education.", "sig_zh": "普莱西案给种族隔离披上宪法外衣长达半个多世纪，直到布朗案才被推翻。", "exp_en": "Separate but equal was never equal — Plessy was the Court's license for Jim Crow.", "exp_zh": "隔离但平等从来不平等——普莱西案是最高法院给吉姆·克劳发的许可证。", "page": 577, "why_term": "separate but equal", "why_term_q": "普莱西案确立的种族隔离宪法原则叫 ______。", "topic_es": "Plessy contra Ferguson", "what_es": "En Plessy contra Ferguson (1896) la Corte Suprema confirmó la segregación de escuelas e instalaciones públicas, legalizando la doctrina de separados pero iguales.", "cause_es": "Los estados del Sur impusieron la segregación de Jim Crow tras la Reconstrucción, y un desafío legal puso a prueba si la segregación violaba la Constitución.", "sig_es": "Plessy dio cobertura constitucional a la segregación durante más de medio siglo, hasta Brown contra la Junta de Educación.", "exp_es": "Separados pero iguales nunca fue igual: Plessy fue la licencia de la Corte para Jim Crow.", "who_es": ["Corte Suprema de EE. UU."], "why_term_q_es": "El principio constitucional de segregación racial establecido en el caso Plessy se llamaba ______."}, {"id": "p6-017", "period": 6, "topic_en": "Atlanta Compromise", "topic_zh": "亚特兰大妥协", "year": 1895, "year_text": "1895", "who": ["Booker T. Washington"], "who_zh": ["布克·T·华盛顿"], "what_en": "In his 1895 Atlanta Compromise address at the Cotton States Exposition, Booker T. Washington assured whites of Black loyalty and accepted social separation: in all things purely social the races could be as separate as the fingers, yet one as the hand in all things essential to mutual progress. He urged Blacks to pursue economic advancement over political agitation.", "what_zh": "1895年华盛顿在棉花州博览会的亚特兰大妥协演说中，向白人保证黑人的忠诚并接受社会隔离：纯粹社交上一切可如五指般分离，在互利进步的一切根本事务上又如手般合一。他主张黑人追求经济进步而非政治抗争。", "cause_en": "In the Jim Crow South, Washington sought an accommodationist strategy that white leaders would tolerate while Blacks built economic strength through schools like Tuskegee.", "cause_zh": "在吉姆·克劳的南方，华盛顿寻求白人能容忍的调和策略，让黑人通过塔斯基吉这样的学校积累经济实力。", "sig_en": "The address made Washington the leading Black spokesman of the era but drew fierce criticism from Du Bois and others demanding full equality.", "sig_zh": "演说使华盛顿成为当时黑人首席代言人，但也招致杜波依斯等人要求完全平等的激烈批评。", "exp_en": "Washington traded political rights for economic opportunity — a bargain Du Bois called a failure.", "exp_zh": "华盛顿用政治权利换经济机会——杜波依斯称这笔交易失败了。", "page": 587, "src": {"text": "In all things that are purely social we can be as separate as the fingers, yet one as the hand in all things essential to mutual progress.", "attr": "Booker T. Washington, Atlanta Compromise address (1895)"}, "topic_es": "El Compromiso de Atlanta", "what_es": "En su discurso del Compromiso de Atlanta de 1895 en la Exposición de los Estados Algodoneros, Booker T. Washington aseguró a los blancos la lealtad negra y aceptó la separación social: en todo lo puramente social las razas podían estar tan separadas como los dedos, pero ser una sola como la mano en todo lo esencial para el progreso mutuo. Instó a los negros a buscar el avance económico antes que la agitación política.", "cause_es": "En el Sur de Jim Crow, Washington buscó una estrategia acomodaticia que los líderes blancos tolerarían mientras los negros construían fortaleza económica mediante escuelas como Tuskegee.", "sig_es": "El discurso convirtió a Washington en el principal portavoz negro de la época, pero atrajo feroces críticas de Du Bois y otros que exigían plena igualdad.", "exp_es": "Washington cambió derechos políticos por oportunidad económica: un trato que Du Bois calificó de fracaso.", "who_es": ["Booker T. Washington"]}, {"id": "p6-018", "period": 6, "topic_en": "Tuskegee Institute", "topic_zh": "塔斯基吉学院", "year": 1881, "year_text": "1881", "who": ["Booker T. Washington"], "who_zh": ["布克·T·华盛顿"], "what_en": "Booker T. Washington founded Tuskegee Institute in Alabama in 1881 to train Black students for self-reliance: women entered teaching and nursing, men the industrial trades or scientific farming.", "what_zh": "华盛顿1881年在亚拉巴马创办塔斯基吉学院，培养黑人自立：女生学师范护理，男生学工业手艺或科学种田。", "cause_en": "Under segregation, Black communities needed their own institutions for education and economic advancement.", "cause_zh": "在隔离制度下，黑人社区需要自己的教育和经济进步机构。", "sig_en": "Tuskegee became the flagship of Washington's program of economic self-help and racial uplift through vocational training.", "sig_zh": "塔斯基吉成为华盛顿以职业培训实现经济自助、种族振兴计划的旗舰。", "exp_en": "Tuskegee embodied Washington's bet: that economic competence would earn what politics could not yet win.", "exp_zh": "塔斯基吉体现了华盛顿的赌注：经济能力能赢得政治尚不能赢得的东西。", "page": 587, "topic_es": "Instituto Tuskegee", "what_es": "Booker T. Washington fundó el Instituto Tuskegee en Alabama en 1881 para formar a estudiantes negros en la autosuficiencia: las mujeres ingresaban a la enseñanza y la enfermería, los hombres a los oficios industriales o la agricultura científica.", "cause_es": "Bajo la segregación, las comunidades negras necesitaban sus propias instituciones para la educación y el avance económico.", "sig_es": "Tuskegee se convirtió en el emblema del programa de Washington de autoayuda económica y elevación racial mediante la formación vocacional.", "exp_es": "Tuskegee encarnó la apuesta de Washington: que la competencia económica ganaría lo que la política aún no podía.", "who_es": ["Booker T. Washington"]}, {"id": "p6-019", "period": 6, "topic_en": "Woman's Christian Temperance Union", "topic_zh": "妇女基督教禁酒联合会", "year": 1874, "year_text": "1874", "who": ["Frances Willard"], "who_zh": ["弗朗西丝·威拉德"], "what_en": "The Woman's Christian Temperance Union, founded in 1874, spread rapidly after charismatic Frances Willard became its leader in 1879. More than any other group of the late nineteenth century, the WCTU launched women into reform, campaigning against liquor and also for domestic-violence, poverty, and education reforms.", "what_zh": "妇女基督教禁酒联合会1874年成立，1879年威拉德接任领袖后迅速扩张。它比19世纪晚期任何团体都更把妇女推入改革，禁酒之外还关注家暴、贫困和教育。", "cause_en": "Its maternalist goal was to curb alcohol abuse, driven by alarm over alcoholism among industrial workers and Civil War veterans.", "cause_zh": "其母性主义目标是遏制酗酒，起因是对工业工人和内战老兵酗酒的忧虑。", "sig_en": "The WCTU gave middle-class women their first mass political organization and a bridge into suffrage and progressive reform.", "sig_zh": "WCTU给了中产阶级妇女第一个群众性政治组织，也成为通向妇女参政权和进步主义改革的桥梁。", "exp_en": "Prohibition was the WCTU's banner, but its real product was politically organized women.", "exp_zh": "禁酒是WCTU的旗帜，它真正的产品是组织起来的妇女。", "page": 589, "topic_es": "Unión Cristiana de Mujeres por la Templanza", "what_es": "La Unión Cristiana de Mujeres por la Templanza, fundada en 1874, se expandió rápidamente después de que la carismática Frances Willard se convirtiera en su líder en 1879. Más que ningún otro grupo de fines del siglo XIX, la WCTU lanzó a las mujeres a la reforma, haciendo campaña contra el licor y también por reformas contra la violencia doméstica, la pobreza y en educación.", "cause_es": "Su objetivo maternalista era frenar el abuso del alcohol, impulsado por la alarma ante el alcoholismo entre obreros industriales y veteranos de la Guerra Civil.", "sig_es": "La WCTU dio a las mujeres de clase media su primera organización política masiva y un puente hacia el sufragio y la reforma progresista.", "exp_es": "La prohibición fue la bandera de la WCTU, pero su verdadero producto fueron mujeres políticamente organizadas.", "who_es": ["Frances Willard"], "img": {"file": "img:f1_3816", "credit": "图源：Henretta《America's History》第8版 p.589"}}, {"id": "p6-020", "period": 6, "topic_en": "National American Woman Suffrage Association", "topic_zh": "全国美国妇女参政权协会", "year": 1890, "year_text": "1890", "who": ["suffragists"], "who_zh": ["妇女参政权论者"], "what_en": "Created in 1890, the National American Woman Suffrage Association became the main organization pressing for women's right to vote, as the Victorian ideal of female moral superiority gradually gave way to modern claims for equal rights.", "what_zh": "1890年成立的全国美国妇女参政权协会成为争取妇女投票权的主要组织；维多利亚式的女性道德优越理想逐渐让位于现代平等权利主张。", "cause_en": "Decades of women's expanding public roles collided with male-dominated politics that ignored their demands.", "cause_zh": "妇女公共角色数十年扩张，却撞上无视其诉求的男性主导政治。", "sig_en": "NAWSA spearheaded the suffrage drive that culminated in the Nineteenth Amendment.", "sig_zh": "该协会领导了最终促成第十九条修正案的参政权运动。", "exp_en": "NAWSA turned maternalist moralizing into a demand for the ballot — equal rights, not just moral influence.", "exp_zh": "NAWSA把母性主义的道德说教变成对选票的要求——要平等权利，不止道德影响力。", "page": 592, "topic_es": "Asociación Nacional Americana por el Sufragio Femenino", "what_es": "Creada en 1890, la Asociación Nacional Americana por el Sufragio Femenino se convirtió en la principal organización que presionaba por el derecho al voto de las mujeres, mientras el ideal victoriano de la superioridad moral femenina cedía gradualmente ante las modernas reivindicaciones de igualdad de derechos.", "cause_es": "Décadas de expansión de los roles públicos de las mujeres chocaron con una política dominada por hombres que ignoraba sus demandas.", "sig_es": "La NAWSA encabezó la campaña sufragista que culminó en la Decimonovena Enmienda.", "exp_es": "La NAWSA convirtió el moralismo maternalista en una demanda de voto: igualdad de derechos, no solo influencia moral.", "who_es": ["sufragistas"]}, {"id": "p6-021", "period": 6, "topic_en": "Ida B. Wells (anti-lynching crusade)", "topic_zh": "艾达·B·威尔斯（反私刑运动）", "year": null, "year_text": "1887–1892", "who": ["Ida B. Wells"], "who_zh": ["艾达·B·威尔斯"], "what_en": "After being thrown bodily from a Tennessee train in 1887 for refusing to leave a whites-only section, young schoolteacher Ida B. Wells launched a lifelong crusade for racial justice. Her mission was to expose the evil of lynching in the South, notably in an 1892 pamphlet published after a Memphis mob murdered three of her friends.", "what_zh": "1887年，年轻女教师威尔斯因拒绝离开白人车厢被粗暴扔下田纳西的火车，从此投身终身的种族正义事业。她的使命是揭露南方私刑之恶，1892年孟菲斯暴徒杀害她三位朋友后她发表了著名小册子。", "cause_en": "The Memphis lynching of three Black grocery-store owners in 1892 and the broader terror of Jim Crow violence demanded a witness.", "cause_zh": "1892年孟菲斯三名黑人杂货店主被私刑处死，吉姆·克劳暴力的恐怖需要见证者。", "sig_en": "Wells pioneered investigative anti-lynching journalism and linked Black women's clubs to the civil-rights struggle.", "sig_zh": "威尔斯开创了调查性反私刑新闻，把黑人妇女俱乐部与民权斗争连接起来。", "exp_en": "Wells proved that a pamphlet and the truth could terrify a system built on terror.", "exp_zh": "威尔斯证明：一本小册子和真相，就能让建立在恐怖上的制度感到恐惧。", "page": 591, "topic_es": "Ida B. Wells (cruzada contra los linchamientos)", "what_es": "Después de ser expulsada a la fuerza de un tren de Tennessee en 1887 por negarse a abandonar una sección solo para blancos, la joven maestra Ida B. Wells lanzó una cruzada de por vida por la justicia racial. Su misión fue exponer el mal de los linchamientos en el Sur, notablemente en un folleto de 1892 publicado después de que una turba de Memphis asesinara a tres de sus amigos.", "cause_es": "El linchamiento en Memphis de tres dueños negros de tiendas de comestibles en 1892 y el terror más amplio de la violencia de Jim Crow exigían un testigo.", "sig_es": "Wells fue pionera del periodismo de investigación contra los linchamientos y vinculó los clubes de mujeres negras con la lucha por los derechos civiles.", "exp_es": "Wells demostró que un folleto y la verdad podían aterrorizar a un sistema construido sobre el terror.", "who_es": ["Ida B. Wells"], "img": {"file": "img:f1_3821", "credit": "图源：Henretta《America's History》第8版 p.591"}}, {"id": "p6-022", "period": 6, "topic_en": "National Association of Colored Women", "topic_zh": "全国有色妇女协会", "year": 1896, "year_text": "1896", "who": ["Black clubwomen"], "who_zh": ["黑人妇女俱乐部成员"], "what_en": "Founded in 1896, the National Association of Colored Women organized Black women for race uplift, using the language of domesticity and respectability to justify work in education, temperance, and anti-lynching campaigns.", "what_zh": "1896年成立的全国有色妇女协会组织黑人妇女投身种族振兴，用家庭与体面的话语为教育、禁酒和反私刑工作正名。", "cause_en": "Black women were excluded from white women's clubs and faced both racism and sexism, so they built their own national network.", "cause_zh": "黑人妇女被白人妇女俱乐部排斥，又同时面对种族和性别歧视，于是建立自己的全国网络。", "sig_en": "The NACW created a durable national network for Black women's activism in the Progressive Era.", "sig_zh": "该协会为进步时代黑人妇女的群众运动建立了持久的全国网络。", "exp_en": "Excluded from both white women's clubs and male-led civil rights groups, Black clubwomen built their own power base — and used it.", "exp_zh": "既被白人妇女俱乐部排斥，又被男性主导的民权团体边缘化，黑人俱乐部妇女建立了自己的权力基地——并用了起来。", "page": 591, "topic_es": "Asociación Nacional de Mujeres de Color", "what_es": "Fundada en 1896, la Asociación Nacional de Mujeres de Color organizó a las mujeres negras para la elevación de la raza, usando el lenguaje de la domesticidad y la respetabilidad para justificar el trabajo en educación, templanza y campañas contra los linchamientos.", "cause_es": "Las mujeres negras estaban excluidas de los clubes de mujeres blancas y enfrentaban tanto el racismo como el sexismo, así que construyeron su propia red nacional.", "sig_es": "La NACW creó una red nacional duradera para el activismo de las mujeres negras en la Era Progresista.", "exp_es": "Excluidas tanto de los clubes de mujeres blancas como de los grupos de derechos civiles liderados por hombres, las mujeres negras de clubes construyeron su propia base de poder, y la usaron.", "who_es": ["Mujeres negras de clubes"], "img": {"file": "img:f1_3821", "credit": "图源：Henretta《America's History》第8版 p.591"}}, {"id": "p6-023", "period": 6, "topic_en": "Comstock Act", "topic_zh": "《康斯托克法》", "year": 1873, "year_text": "1873", "who": ["Anthony Comstock"], "who_zh": ["安东尼·康斯托克"], "what_en": "The Comstock Act of 1873 banned circulation of most information about sex and birth control through the mail, enforcing Victorian moral standards by federal law.", "what_zh": "1873年《康斯托克法》禁止通过邮寄传播大多数关于性和节育的信息，以联邦法律强制维多利亚道德标准。", "cause_en": "Comstock's campaign against obscenity rode Victorian anxieties about sexuality amid rapid urbanization.", "cause_zh": "康斯托克的反淫秽运动乘着快速城市化中维多利亚时代对性的焦虑。", "sig_en": "It criminalized birth-control information for decades and became a prime target of later reformers like Margaret Sanger.", "sig_zh": "它把节育信息定罪数十年，成为后来桑格等改革者的主要攻击目标。", "exp_en": "The Comstock Act made the post office America's moral censor.", "exp_zh": "康斯托克法让邮局成了美国的道德审查官。", "page": 585, "topic_es": "Ley Comstock", "what_es": "La Ley Comstock de 1873 prohibió la circulación por correo de casi toda información sobre sexo y control de la natalidad, imponiendo por ley federal los estándares morales victorianos.", "cause_es": "La campaña de Comstock contra la obscenidad cabalgó sobre las ansiedades victorianas acerca de la sexualidad en medio de la rápida urbanización.", "sig_es": "Criminalizó la información sobre anticoncepción durante décadas y se convirtió en blanco principal de reformistas posteriores como Margaret Sanger.", "exp_es": "La Ley Comstock convirtió a la oficina de correos en el censor moral de Estados Unidos.", "who_es": ["Anthony Comstock"], "img": {"file": "img:f1_3806", "credit": "图源：Henretta《America's History》第8版 p.585"}}, {"id": "p6-024", "period": 6, "topic_en": "Social Darwinism", "topic_zh": "社会达尔文主义", "year": null, "year_text": "1870s", "who": ["Herbert Spencer", "William Graham Sumner"], "who_zh": ["赫伯特·斯宾塞", "威廉·格雷厄姆·萨姆纳"], "what_en": "British philosopher Herbert Spencer spun out a theory of human advance through survival of the fittest. Social Darwinism found its American champion in Yale sociologist William Graham Sumner, who declared competition a law of nature like gravity and said millionaires were naturally selected.", "what_zh": "英国哲学家斯宾塞提出人类经适者生存而进步的理论。社会达尔文主义在美国的旗手是耶鲁社会学家萨姆纳，他宣称竞争如重力般是自然法则，百万富翁是自然选择的结果。", "cause_en": "Darwin's theory of evolution prompted influential thinkers to justify economic inequality as a law of nature.", "cause_zh": "达尔文进化论促使有影响的思想家把经济不平等说成自然法则。", "sig_en": "It provided an intellectual defense of industrial inequality, though critics called it an excuse for industrialization's worst excesses.", "sig_zh": "它为工业不平等提供思想辩护，但批评者称其不过是为工业化最恶劣的过度行为开脱。", "exp_en": "Social Darwinism turned Darwin's finches into a defense of millionaires.", "exp_zh": "社会达尔文主义把达尔文的雀鸟变成了百万富翁的辩护词。", "page": 594, "why_term": "survival of the fittest", "why_term_q": "斯宾塞用来解释人类社会进步、被萨姆纳借用的核心概念是 ______。", "topic_es": "Darwinismo social", "what_es": "El filósofo británico Herbert Spencer elaboró una teoría del avance humano mediante la supervivencia de los más aptos. El darwinismo social encontró su campeón estadounidense en el sociólogo de Yale William Graham Sumner, quien declaró que la competencia era una ley de la naturaleza como la gravedad y dijo que los millonarios eran seleccionados naturalmente.", "cause_es": "La teoría de la evolución de Darwin llevó a pensadores influyentes a justificar la desigualdad económica como ley de la naturaleza.", "sig_es": "Proporcionó una defensa intelectual de la desigualdad industrial, aunque los críticos lo llamaron una excusa para los peores excesos de la industrialización.", "exp_es": "El darwinismo social convirtió los pinzones de Darwin en una defensa de los millonarios.", "who_es": ["Herbert Spencer", "William Graham Sumner"], "why_term_q_es": "El concepto central que Spencer usó para explicar el progreso de la sociedad humana, adoptado por Sumner, era ______."}, {"id": "p6-025", "period": 6, "topic_en": "Eugenics", "topic_zh": "优生学", "year": null, "year_text": "1900s–1920s", "who": ["eugenicists"], "who_zh": ["优生学者"], "what_en": "Eugenics, the pseudo-science of improving the human race by controlling reproduction, reached its height in the 1900s–1920s, inspiring forced-sterilization laws and immigration restriction.", "what_zh": "优生学——通过控制繁殖来改良人类的伪科学——在1900至1920年代达到顶峰，催生了强制绝育法和移民限制。", "cause_en": "Misapplied Darwinian ideas and nativist fears of unfit immigrants gave it respectability.", "cause_zh": "被误用的达尔文思想和本土主义者对劣等移民的恐惧给了它体面外衣。", "sig_en": "It lent scientific prestige to racism and shaped restrictive immigration policy for decades.", "sig_zh": "它给种族主义披上科学外衣，塑造了数十年的限制性移民政策。", "exp_en": "Eugenics was Social Darwinism with a scalpel — and the state holding the handle.", "exp_zh": "优生学是拿着手术刀的社会达尔文主义——刀柄握在国家手里。", "page": 594, "topic_es": "Eugenesia", "what_es": "La eugenesia, la pseudociencia de mejorar la raza humana controlando la reproducción, alcanzó su apogeo en las décadas de 1900 a 1920, inspirando leyes de esterilización forzada y restricción migratoria.", "cause_es": "Las ideas darwinianas mal aplicadas y los temores nativistas hacia inmigrantes no aptos le dieron respetabilidad.", "sig_es": "Prestó prestigio científico al racismo y moldeó la política migratoria restrictiva durante décadas.", "exp_es": "La eugenesia fue el darwinismo social con bisturí, y el Estado sosteniendo el mango.", "who_es": ["eugenistas"]}, {"id": "p6-026", "period": 6, "topic_en": "Sierra Club", "topic_zh": "塞拉俱乐部", "year": 1892, "year_text": "1892", "who": ["John Muir"], "who_zh": ["约翰·缪尔"], "what_en": "Naturalist John Muir founded the Sierra Club in 1892 to preserve wilderness, part of a new conservation movement that also produced the Appalachian Mountain Club (1876) and the National Audubon Society.", "what_zh": "博物学家约翰·缪尔1892年创办塞拉俱乐部以保护荒野，这是新自然保护运动的一部分，同期的还有阿巴拉契亚山地俱乐部（1876）和全国奥杜邦学会。", "cause_en": "Industrialization was destroying nature while a new middle-class love of hiking and camping got more Americans outdoors.", "cause_zh": "工业化在破坏自然，而新兴中产阶级对徒步露营的热爱让更多美国人走向户外。", "sig_en": "The Sierra Club became the leading voice for wilderness preservation and helped win national parks, forests, and wildlife refuges.", "sig_zh": "塞拉俱乐部成为荒野保护的主要代言人，帮助赢得了国家公园、国家森林和野生动物保护区。", "exp_en": "Muir taught Americans that wilderness had value beyond what could be logged or mined from it.", "exp_zh": "缪尔教会美国人：荒野的价值超出能砍伐和开采的东西。", "page": 583, "topic_es": "Sierra Club", "what_es": "El naturalista John Muir fundó el Sierra Club en 1892 para preservar la naturaleza virgen, parte de un nuevo movimiento conservacionista que también produjo el Club de Montaña de los Apalaches (1876) y la Sociedad Nacional Audubon.", "cause_es": "La industrialización estaba destruyendo la naturaleza mientras un nuevo amor de la clase media por el senderismo y el campismo llevaba a más estadounidenses al aire libre.", "sig_es": "El Sierra Club se convirtió en la principal voz de la preservación de la naturaleza virgen y ayudó a ganar parques nacionales, bosques y refugios de vida silvestre.", "exp_es": "Muir enseñó a los estadounidenses que la naturaleza virgen tenía valor más allá de lo que se podía talar o extraer de ella.", "who_es": ["John Muir"]}, {"id": "p6-027", "period": 6, "topic_en": "Yellowstone (first national park)", "topic_zh": "黄石（第一个国家公园）", "year": 1872, "year_text": "1872", "who": ["U.S. Congress"], "who_zh": ["美国国会"], "what_en": "In 1872 Congress established Yellowstone as the first national park, beginning federal protection of scenic lands.", "what_zh": "1872年国会设立黄石为第一个国家公园，开启了联邦对风景名胜地的保护。", "cause_en": "Awe at western landscapes and early conservation sentiment, later championed by figures like John Muir, pushed the idea.", "cause_zh": "对西部景观的惊叹和早期的保护意识（后由缪尔等人倡导）推动了这一创举。", "sig_en": "It created the national-park idea, later administered by the National Park Service (1916).", "sig_zh": "它创造了国家公园理念，后由国家公园管理局（1916）管理。", "exp_en": "Yellowstone was America's declaration that some places are too magnificent to be owned.", "exp_zh": "黄石是美国的宣言：有些地方壮美到不该被私人占有。", "page": 583, "topic_es": "Yellowstone (primer parque nacional)", "what_es": "En 1872 el Congreso estableció Yellowstone como el primer parque nacional, iniciando la protección federal de tierras escénicas.", "cause_es": "El asombro ante los paisajes del oeste y el temprano sentimiento conservacionista, defendido después por figuras como John Muir, impulsaron la idea.", "sig_es": "Creó la idea del parque nacional, administrada después por el Servicio de Parques Nacionales (1916).", "exp_es": "Yellowstone fue la declaración de Estados Unidos de que algunos lugares son demasiado magníficos para ser poseídos.", "who_es": ["Congreso de EE. UU."]}, {"id": "p6-028", "period": 6, "topic_en": "National Park Service", "topic_zh": "国家公园管理局", "year": 1916, "year_text": "1916", "who": ["U.S. Congress"], "who_zh": ["美国国会"], "what_en": "Created in 1916, the National Park Service took over professional administration of the growing system of national parks and monuments.", "what_zh": "1916年成立的国家公园管理局接管了日益增多的国家公园和历史遗迹的专业管理。", "cause_en": "The park system had grown piecemeal since Yellowstone, and progressives wanted unified professional management.", "cause_zh": "自黄石以来公园体系零散增长，进步主义者要求统一的专业管理。", "sig_en": "It institutionalized federal conservation as a permanent government function.", "sig_zh": "它把联邦自然保护制度化为永久的政府职能。", "exp_en": "From Yellowstone to a whole system — the Park Service made conservation a permanent American institution.", "exp_zh": "从黄石到整个体系——公园管理局让自然保护成为永久的美国制度。", "page": 583, "topic_es": "Servicio de Parques Nacionales", "what_es": "Creado en 1916, el Servicio de Parques Nacionales asumió la administración profesional del creciente sistema de parques y monumentos nacionales.", "cause_es": "El sistema de parques había crecido de forma fragmentaria desde Yellowstone, y los progresistas querían una gestión profesional unificada.", "sig_es": "Institucionalizó la conservación federal como función permanente del gobierno.", "exp_es": "De Yellowstone a todo un sistema: el Servicio de Parques hizo de la conservación una institución permanente estadounidense.", "who_es": ["Congreso de EE. UU."]}, {"id": "p6-029", "period": 6, "topic_en": "Mark Twain", "topic_zh": "马克·吐温", "year": null, "year_text": "late nineteenth century", "who": ["Samuel Langhorne Clemens"], "who_zh": ["塞缪尔·朗霍恩·克莱门斯"], "what_en": "Novelist Mark Twain (Samuel Langhorne Clemens), a master of literary realism, rejected Victorian certainties and even Christian faith, exemplifying how new intellectual currents challenged old beliefs.", "what_zh": "现实主义文学大师马克·吐温拒绝维多利亚时代的确定性乃至基督教信仰，体现了新思想潮流如何挑战旧信念。", "cause_en": "Industrialization, Darwinism, and disillusionment shook the pieties of his grandparents' generation.", "cause_zh": "工业化、达尔文主义和幻灭动摇了他祖辈的虔诚信念。", "sig_en": "His realist writing helped define a distinctively American literature confronting modernity.", "sig_zh": "他的现实主义写作帮助确立了直面现代性的独特美国文学。", "exp_en": "Twain laughed at Victorian pieties — and made American literature grow up.", "exp_zh": "吐温嘲笑维多利亚的虔诚——并让美国文学长大成人。", "page": 594, "topic_es": "Mark Twain", "what_es": "El novelista Mark Twain (Samuel Langhorne Clemens), maestro del realismo literario, rechazó las certezas victorianas e incluso la fe cristiana, ejemplificando cómo las nuevas corrientes intelectuales desafiaban las viejas creencias.", "cause_es": "La industrialización, el darwinismo y la desilusión sacudieron las piedadades de la generación de sus abuelos.", "sig_es": "Su escritura realista ayudó a definir una literatura estadounidense distintiva que confrontaba la modernidad.", "exp_es": "Twain se rio de las piedadades victorianas, e hizo madurar a la literatura estadounidense.", "who_es": ["Samuel Langhorne Clemens"]}, {"id": "p6-030", "period": 6, "topic_en": "World's Columbian Exposition (1893)", "topic_zh": "芝加哥世界哥伦比亚博览会（1893）", "year": 1893, "year_text": "1893", "who": ["Chicago boosters"], "who_zh": ["芝加哥主办者"], "what_en": "The 1893 Chicago World's Columbian Exposition dazzled visitors with strings of electric lights and exhibits of industrial achievement; ragtime was introduced to national audiences there.", "what_zh": "1893年芝加哥世界哥伦比亚博览会以成串电灯和工业成就展让游客目眩；拉格泰姆音乐在那里首次介绍给全国观众。", "cause_en": "Chicago's boosters wanted to display American industrial and cultural achievement to the world.", "cause_zh": "芝加哥的推动者想向世界展示美国的工业和文化成就。", "sig_en": "The fair showcased the new consumer culture and modernism, even as its exhibits reflected the era's racial hierarchies.", "sig_zh": "博览会展示了新消费文化和现代主义，尽管其展陈也反映了当时的种族等级观。", "exp_en": "The White City sold America a vision of the future — electric, orderly, and modern.", "exp_zh": "白城向美国兜售了一幅未来图景——电气化、有序、现代。", "page": 593, "topic_es": "Exposición Colombina Mundial (1893)", "what_es": "La Exposición Colombina Mundial de Chicago de 1893 deslumbró a los visitantes con hileras de luces eléctricas y exhibiciones de logros industriales; el ragtime se presentó allí a audiencias nacionales.", "cause_es": "Los promotores de Chicago querían mostrar al mundo el logro industrial y cultural estadounidense.", "sig_es": "La feria exhibió la nueva cultura del consumo y el modernismo, aun cuando sus exhibiciones reflejaban las jerarquías raciales de la época.", "exp_es": "La Ciudad Blanca vendió a Estados Unidos una visión del futuro: eléctrica, ordenada y moderna.", "who_es": ["Promotores de Chicago"], "img": {"file": "img:f1_3825", "credit": "图源：Henretta《America's History》第8版 p.593"}}, {"id": "p6-031", "period": 6, "topic_en": "Hull House", "topic_zh": "赫尔馆", "year": 1889, "year_text": "1889", "who": ["Jane Addams", "Ellen Gates Starr"], "who_zh": ["简·亚当斯", "埃伦·盖茨·斯塔尔"], "what_en": "In 1889 Jane Addams and Ellen Gates Starr founded Hull House in Chicago, the most famous social settlement, where middle-class volunteers lived among immigrants and offered kindergartens, clinics, and labor organizing.", "what_zh": "1889年简·亚当斯和埃伦·盖茨·斯塔尔在芝加哥创办赫尔馆——最著名的睦邻组织之家，中产阶级志愿者住在移民中间，提供幼儿园、诊所并组织劳工。", "cause_en": "Urban poverty and slums convinced reformers that personal settlement among the poor could uplift them.", "cause_zh": "城市贫困和贫民窟让改革者相信，住到穷人中间能提升他们。", "sig_en": "Settlements became proving grounds for progressive reforms — Florence Kelley and Margaret Sanger both worked through them — and drew reformers into national politics.", "sig_zh": "睦邻之家成为进步主义改革的试验场——凯利和桑格都经此起步，并把改革者带入全国政治。", "exp_en": "Hull House invented a new kind of politics: reform by living with the people you hoped to help.", "exp_zh": "赫尔馆发明了一种新政治：与你想帮助的人住在一起去改革。", "page": 627, "topic_es": "Hull House", "what_es": "En 1889 Jane Addams y Ellen Gates Starr fundaron Hull House en Chicago, el asentamiento social más famoso, donde voluntarias de clase media vivían entre inmigrantes y ofrecían jardines de infancia, clínicas y organización laboral.", "cause_es": "La pobreza urbana y los barrios bajos convencieron a las reformistas de que establecerse personalmente entre los pobres podía elevarlos.", "sig_es": "Los asentamientos se convirtieron en campos de prueba para las reformas progresistas — Florence Kelley y Margaret Sanger trabajaron a través de ellos — y llevaron a las reformistas a la política nacional.", "exp_es": "Hull House inventó un nuevo tipo de política: reformar viviendo con las personas a las que se esperaba ayudar.", "who_es": ["Jane Addams", "Ellen Gates Starr"], "img": {"file": "img:f2_698", "credit": "图源：Henretta《America's History》第8版 p.627"}}, {"id": "p6-032", "period": 6, "topic_en": "The Jungle / Pure Food and Drug Act", "topic_zh": "《丛林》/《纯净食品和药品法》", "year": 1906, "year_text": "1906", "who": ["Upton Sinclair"], "who_zh": ["厄普顿·辛克莱"], "what_en": "In 1906 journalist Upton Sinclair's novel The Jungle exposed appalling conditions in Chicago meatpacking plants. What caught the nation's attention was not workers' plight but rotten meat and filthy packing conditions, so Congress passed the Pure Food and Drug Act (1906) and created the federal Food and Drug Administration.", "what_zh": "1906年记者辛克莱的小说《丛林》揭露芝加哥肉类加工厂骇人状况。抓住全国注意力的不是工人苦难而是腐肉和肮脏的加工环境，于是国会通过1906年《纯净食品和药品法》并创建联邦食品药品管理局。", "cause_en": "Muckraking journalism and Progressive Era alarm over industrial abuses created the audience for exposure.", "cause_zh": "扒粪新闻和进步时代对工业弊病的警觉造就了揭露的听众。", "sig_en": "It showed how urban reformers could force national legislation — though Sinclair joked he aimed at the public's heart and hit its stomach.", "sig_zh": "它显示城市改革者如何迫使全国立法——辛克莱自嘲他瞄准公众的心脏，却击中了胃。", "exp_en": "The Jungle is the classic case of reform succeeding for the wrong reason — and succeeding anyway.", "exp_zh": "《丛林》是改革因错误理由成功——但终究成功了的经典案例。", "page": 629, "topic_es": "La jungla / Ley de Alimentos y Medicamentos Puros", "what_es": "En 1906 la novela La jungla del periodista Upton Sinclair expuso las condiciones atroces en las plantas empacadoras de carne de Chicago. Lo que captó la atención nacional no fue la difícil situación de los obreros sino la carne podrida y las condiciones inmundas del empaque, así que el Congreso aprobó la Ley de Alimentos y Medicamentos Puros (1906) y creó la Administración federal de Alimentos y Medicamentos.", "cause_es": "El periodismo muckraker y la alarma de la Era Progresista ante los abusos industriales crearon la audiencia para la denuncia.", "sig_es": "Mostró cómo los reformistas urbanos podían forzar legislación nacional, aunque Sinclair bromeó que había apuntado al corazón del público y le había dado en el estómago.", "exp_es": "La jungla es el caso clásico de una reforma que triunfa por la razón equivocada, y triunfa de todos modos.", "who_es": ["Upton Sinclair"], "img": {"file": "img:f2_702", "credit": "图源：Henretta《America's History》第8版 p.629"}}, {"id": "p6-033", "period": 6, "topic_en": "Triangle Shirtwaist Fire", "topic_zh": "三角衬衫厂大火", "year": 1911, "year_text": "March 1911", "who": ["garment workers"], "who_zh": ["制衣工人"], "what_en": "A 1911 fire at New York's Triangle Shirtwaist Company killed scores of young garment workers, many of them immigrant women. Eyewitness reporter William G. Shepherd described girls at the windows with flames beating in their faces, leaping to the sidewalk below.", "what_zh": "1911年纽约三角衬衫公司大火烧死大批年轻制衣女工，多为移民女性。目击记者谢泼德描述姑娘们挤在窗前、火焰扑面，纵身跃下人行道。", "cause_en": "Locked doors, flammable materials, and lax safety enforcement in sweatshops turned a fire into a massacre.", "cause_zh": "血汗工厂紧锁的门、易燃物和松懈的安全执法，把火灾变成屠杀。", "sig_en": "The tragedy galvanized factory-safety and labor-protection reforms across the nation.", "sig_zh": "这场悲剧推动了全国工厂安全和劳工保护改革。", "exp_en": "The Triangle fire made workplace safety a cause the whole nation could see — in falling bodies.", "exp_zh": "三角大火让工作场所安全成为全国看得见的事业——以坠落的身体为代价。", "page": 630, "src": {"text": "I saw every feature of the tragedy visible from outside the building. It was the thud of a speeding, living body on a stone sidewalk. I looked up — saw that there were scores of girls at the windows. The flames from the floor below were beating in their faces.", "attr": "William G. Shepherd, United Press reporter, eyewitness account (as printed in American Voices)"}, "topic_es": "Incendio de la Triangle Shirtwaist", "what_es": "Un incendio de 1911 en la Triangle Shirtwaist Company de Nueva York mató a decenas de jóvenes trabajadores de la confección, muchas de ellas mujeres inmigrantes. El reportero testigo William G. Shepherd describió a muchachas en las ventanas con las llamas golpeándoles la cara, saltando a la acera.", "cause_es": "Puertas cerradas con llave, materiales inflamables y una laxa aplicación de la seguridad en los talleres clandestinos convirtieron un incendio en una masacre.", "sig_es": "La tragedia galvanizó las reformas de seguridad fabril y protección laboral en toda la nación.", "exp_es": "El incendio de la Triangle hizo de la seguridad laboral una causa que toda la nación pudo ver: en cuerpos cayendo.", "who_es": ["trabajadores de la confección"]}, {"id": "p6-034", "period": 6, "topic_en": "Yellow journalism / muckrakers", "topic_zh": "黄色新闻/扒粪者", "year": null, "year_text": "1890s", "who": ["Joseph Pulitzer", "William Randolph Hearst"], "who_zh": ["约瑟夫·普利策", "威廉·伦道夫·赫斯特"], "what_en": "Joseph Pulitzer and William Randolph Hearst built mass circulation with sensational investigations and human-interest stories; the Yellow Kid comics gave such papers the name yellow journalism, while investigative reporters exposing corruption earned the name muckrakers.", "what_zh": "普利策和赫斯特靠耸人听闻的调查和人情味故事建立大众发行量；黄孩子漫画给了这类报纸黄色新闻之名，而揭露腐败的调查记者则被称为扒粪者。", "cause_en": "Urban mass audiences and fierce newspaper competition rewarded sensation.", "cause_zh": "城市大众读者和激烈的报业竞争奖励耸人听闻。", "sig_en": "Sensational press helped whip up pressure for war against Spain and fed progressive reform campaigns.", "sig_zh": "煽情报刊煽动了对西班牙开战的压力，也助推了进步主义改革运动。", "exp_en": "The muckrakers proved that in the age of the masses, exposure was a political weapon.", "exp_zh": "扒粪者证明：在大众时代，揭露是一种政治武器。", "page": 619, "topic_es": "Prensa amarilla / muckrakers", "what_es": "Joseph Pulitzer y William Randolph Hearst construyeron circulación masiva con investigaciones sensacionalistas e historias de interés humano; las tiras del Yellow Kid dieron a esos periódicos el nombre de prensa amarilla, mientras los reporteros de investigación que exponían la corrupción ganaron el nombre de muckrakers.", "cause_es": "Las audiencias urbanas masivas y la feroz competencia periodística premiaban el sensacionalismo.", "sig_es": "La prensa sensacionalista ayudó a azuzar la presión por la guerra contra España y alimentó las campañas de reforma progresista.", "exp_es": "Los muckrakers demostraron que en la era de las masas la denuncia era un arma política.", "who_es": ["Joseph Pulitzer", "William Randolph Hearst"]}, {"id": "p6-035", "period": 6, "topic_en": "Political machines", "topic_zh": "政治机器", "year": null, "year_text": "late 1800s", "who": ["machine bosses"], "who_zh": ["机器老板"], "what_en": "Urban political machines traded jobs and services for votes. Machine-style governments achieved notable successes like public works, but entrenched corruption; reformers challenged them through the National Municipal League and new forms of city government.", "what_zh": "城市政治机器以工作和服务换选票。机器式政府在公共工程等方面颇有建树，但也固化腐败；改革者通过全国市政联盟和新的市政形式挑战它们。", "cause_en": "Rapid immigrant growth created demand for services that formal government failed to provide, and machines filled the gap.", "cause_zh": "移民快速增长带来正式政府无力提供的服务需求，机器填补了空白。", "sig_en": "Machines dominated city politics for decades, and the struggle against them defined urban progressivism.", "sig_zh": "机器主导城市政治数十年，反机器斗争定义了城市进步主义。", "exp_en": "The machine was corrupt and indispensable at once — which is why it lasted so long.", "exp_zh": "机器既腐败又不可或缺——这正是它长盛不衰的原因。", "page": 619, "topic_es": "Maquinarias políticas", "what_es": "Las maquinarias políticas urbanas intercambiaban empleos y servicios por votos. Los gobiernos de estilo maquinista lograron éxitos notables como obras públicas, pero afianzaron la corrupción; los reformistas las desafiaron a través de la Liga Municipal Nacional y nuevas formas de gobierno municipal.", "cause_es": "El rápido crecimiento inmigrante creó demanda de servicios que el gobierno formal no proveía, y las maquinarias llenaron el vacío.", "sig_es": "Las maquinarias dominaron la política urbana durante décadas, y la lucha contra ellas definió el progresismo urbano.", "exp_es": "La maquinaria era corrupta e indispensable a la vez, razón por la cual duró tanto.", "who_es": ["jefes de la maquinaria política"]}, {"id": "p6-036", "period": 6, "topic_en": "Tenement House Law", "topic_zh": "《公寓房法》", "year": 1901, "year_text": "1901", "who": ["New York reformers"], "who_zh": ["纽约改革者"], "what_en": "New York passed the Tenement House Law in 1901 to regulate the crowded, unsanitary tenement apartments where hundreds of thousands of immigrants lived — in the Eleventh Ward an average of 986 persons occupied each acre.", "what_zh": "纽约1901年通过《公寓房法》，管制数十万移民居住的拥挤肮脏的公寓房——第十一区平均每英亩住986人。", "cause_en": "Jacob Riis's exposes and reformers' alarm at slum conditions forced the issue.", "cause_zh": "雅各布·里斯的揭露和改革者对贫民窟状况的警觉迫使问题提上日程。", "sig_en": "It was a landmark of housing reform, though enforcement remained difficult.", "sig_zh": "它是住房改革的里程碑，尽管执行依然困难。", "exp_en": "The law admitted what landlords denied: the state could tell you how to house people.", "exp_zh": "这部法律承认了房东否认的事：国家可以规定你如何安置人。", "page": 614, "topic_es": "Ley de Casas de Vecindad", "what_es": "Nueva York aprobó la Ley de Casas de Vecindad en 1901 para regular los atestados e insalubres apartamentos de vecindad donde vivían cientos de miles de inmigrantes; en el Distrito Once un promedio de 986 personas ocupaba cada acre.", "cause_es": "Las denuncias de Jacob Riis y la alarma de los reformistas ante las condiciones de los barrios bajos forzaron el tema.", "sig_es": "Fue un hito de la reforma de vivienda, aunque su aplicación siguió siendo difícil.", "exp_es": "La ley admitió lo que los caseros negaban: que el Estado podía decirte cómo alojar a las personas.", "who_es": ["Reformistas de Nueva York"], "img": {"file": "img:f2_660", "credit": "图源：Henretta《America's History》第8版 p.614"}}, {"id": "p6-037", "period": 6, "topic_en": "National Consumers' League", "topic_zh": "全国消费者联盟", "year": 1899, "year_text": "1899", "who": ["Florence Kelley", "Josephine Shaw Lowell"], "who_zh": ["弗洛伦斯·凯利", "约瑟芬·肖·洛厄尔"], "what_en": "Josephine Shaw Lowell founded the New York Consumers' League in 1890 after concluding charity was not enough; by 1899 it had become the National Consumers' League under Hull House worker Florence Kelley, who believed only government oversight could protect exploited workers. The league urged shoppers to patronize only stores with fair wages.", "what_zh": "洛厄尔认定慈善不够，1890年创办纽约消费者联盟；1899年它在赫尔馆工作者凯利领导下成为全国消费者联盟，凯利相信只有政府监督能保护被剥削的工人。联盟呼吁消费者只光顾工资公平的商店。", "cause_en": "Lowell's years of struggling to aid poverty-stricken individuals convinced her that structural, governmental solutions were needed.", "cause_zh": "洛厄尔多年救济贫困个人的挣扎让她确信需要结构性、政府性的解决办法。", "sig_en": "The NCL became one of the most powerful progressive organizations advocating worker-protection laws, especially for women.", "sig_zh": "该联盟成为倡导劳工保护法（尤其保护妇女）最有力的进步组织之一。", "exp_en": "The NCL turned shopping into politics: every purchase a vote for fair labor.", "exp_zh": "全国消费者联盟把购物变成政治：每一次购买都是为公平劳工投票。", "page": 629, "topic_es": "Liga Nacional de Consumidores", "what_es": "Josephine Shaw Lowell fundó la Liga de Consumidores de Nueva York en 1890 tras concluir que la caridad no bastaba; para 1899 se había convertido en la Liga Nacional de Consumidores bajo la trabajadora de Hull House Florence Kelley, quien creía que solo la supervisión gubernamental podía proteger a los obreros explotados. La liga instaba a los compradores a frecuentar solo tiendas con salarios justos.", "cause_es": "Los años de Lowell luchando por ayudar a personas sumidas en la pobreza la convencieron de que se necesitaban soluciones estructurales y gubernamentales.", "sig_es": "La NCL se convirtió en una de las organizaciones progresistas más poderosas en defensa de leyes de protección obrera, especialmente para las mujeres.", "exp_es": "La NCL convirtió las compras en política: cada compra un voto por el trabajo justo.", "who_es": ["Florence Kelley", "Josephine Shaw Lowell"], "img": {"file": "img:f2_702", "credit": "图源：Henretta《America's History》第8版 p.629"}}, {"id": "p6-038", "period": 6, "topic_en": "Women's Trade Union League", "topic_zh": "妇女工会联盟", "year": 1903, "year_text": "1903", "who": ["working women", "middle-class reformers"], "who_zh": ["职业妇女", "中产阶级改革者"], "what_en": "The Women's Trade Union League, founded in 1903, allied middle-class reformers with working women to organize female workers and support their strikes in the garment trades and beyond.", "what_zh": "1903年成立的妇女工会联盟把中产阶级改革者与职业妇女结盟，组织女工并支持她们在制衣业等行业的罢工。", "cause_en": "Women workers earned low wages and were largely excluded from male-dominated unions like the AFL.", "cause_zh": "女工工资低廉，又基本被AFL等男性主导的工会排斥在外。", "sig_en": "It bridged class divides in the labor movement and advanced protective labor legislation for women.", "sig_zh": "它弥合了劳工运动中的阶级鸿沟，推动了保护妇女的劳工立法。", "exp_en": "Rich reformers and poor strikers discovered they needed each other.", "exp_zh": "富有的改革者和贫穷的罢工者发现彼此需要对方。", "page": 629, "topic_es": "Liga Sindical Femenina", "what_es": "La Liga Sindical Femenina, fundada en 1903, alió a reformistas de clase media con mujeres trabajadoras para organizar a las obreras y apoyar sus huelgas en la confección y más allá.", "cause_es": "Las obreras ganaban salarios bajos y estaban mayormente excluidas de sindicatos dominados por hombres como la AFL.", "sig_es": "Tendió un puente entre clases en el movimiento obrero y avanzó la legislación protectora del trabajo femenino.", "exp_es": "Reformistas ricas y huelguistas pobres descubrieron que se necesitaban mutuamente.", "who_es": ["mujeres trabajadoras", "reformistas de clase media"], "img": {"file": "img:f2_702", "credit": "图源：Henretta《America's History》第8版 p.629"}}, {"id": "p6-039", "period": 6, "topic_en": "Margaret Sanger / birth control movement", "topic_zh": "玛格丽特·桑格/节育运动", "year": null, "year_text": "1910s", "who": ["Margaret Sanger"], "who_zh": ["玛格丽特·桑格"], "what_en": "Nurse Margaret Sanger, horrified by women's suffering from constant pregnancies, launched a crusade for what she called birth control. Her newspaper column What Every Girl Should Know drew an indictment for violating obscenity laws, and the resulting publicity helped launch a national birth-control movement.", "what_zh": "护士桑格目睹妇女因不断怀孕受苦，发起了她称为节育的运动。她的报纸专栏《每个女孩都应知道》招致违反淫秽法起诉，随之而来的舆论关注帮助发起了全国节育运动。", "cause_en": "Comstock laws criminalized contraceptive information while poor women bore the cost of endless childbearing.", "cause_zh": "康斯托克法把避孕信息定罪，而贫穷妇女承担着无休止生育的代价。", "sig_en": "She founded the movement that challenged Victorian sexual morality and eventually became Planned Parenthood.", "sig_zh": "她创立的运动挑战了维多利亚性道德，最终发展为计划生育联合会。", "exp_en": "Sanger turned a private suffering into a public right.", "exp_zh": "桑格把私人的苦难变成了公共的权利。", "page": 628, "topic_es": "Margaret Sanger / movimiento por el control de la natalidad", "what_es": "La enfermera Margaret Sanger, horrorizada por el sufrimiento de las mujeres a causa de embarazos constantes, lanzó una cruzada por lo que llamó control de la natalidad. Su columna periodística Lo que toda muchacha debería saber atrajo una acusación por violar las leyes de obscenidad, y la publicidad resultante ayudó a lanzar un movimiento nacional por el control de la natalidad.", "cause_es": "Las leyes Comstock criminalizaban la información anticonceptiva mientras las mujeres pobres pagaban el costo de una maternidad incesante.", "sig_es": "Fundó el movimiento que desafió la moral sexual victoriana y eventualmente se convirtió en Planned Parenthood.", "exp_es": "Sanger convirtió un sufrimiento privado en un derecho público.", "who_es": ["Margaret Sanger"]}, {"id": "p6-040", "period": 6, "topic_en": "City Beautiful movement", "topic_zh": "城市美化运动", "year": null, "year_text": "1901", "who": ["urban planners"], "who_zh": ["城市规划者"], "what_en": "The City Beautiful movement, launched with the 1901 plan for Washington, D.C., sought to remake cities with grand boulevards, parks, and civic monuments.", "what_zh": "城市美化运动以1901年华盛顿特区规划为开端，主张用宏伟林荫道、公园和市政纪念建筑重塑城市。", "cause_en": "Reformers believed beautiful surroundings would uplift urban residents and counter slum disorder.", "cause_zh": "改革者相信优美环境能提升市民、抵消贫民窟的失序。", "sig_en": "It reshaped American city planning, though critics noted its benefits flowed more to elites than to the poor.", "sig_zh": "它重塑了美国城市规划，尽管批评者指出其好处更多流向精英而非穷人。", "exp_en": "Beauty as reform: the movement believed grand avenues could make grand citizens.", "exp_zh": "以美为改革：该运动相信宏伟大道能造就宏伟公民。", "page": 626, "topic_es": "Movimiento Ciudad Bella", "what_es": "El movimiento Ciudad Bella, lanzado con el plan de 1901 para Washington, D.C., buscó rehacer las ciudades con grandes bulevares, parques y monumentos cívicos.", "cause_es": "Los reformistas creían que entornos bellos elevarían a los residentes urbanos y contrarrestarían el desorden de los barrios bajos.", "sig_es": "Remodeló la planificación urbana estadounidense, aunque los críticos notaron que sus beneficios fluían más hacia las élites que hacia los pobres.", "exp_es": "Belleza como reforma: el movimiento creía que las grandes avenidas podían formar grandes ciudadanos.", "who_es": ["urbanistas"], "img": {"file": "img:f2_696", "credit": "图源：Henretta《America's History》第8版 p.626"}}, {"id": "p6-041", "period": 6, "topic_en": "Ellis Island", "topic_zh": "埃利斯岛", "year": 1892, "year_text": "1892", "who": ["arriving immigrants"], "who_zh": ["抵美移民"], "what_en": "New York's Ellis Island opened in 1892 as the federal immigration station through which arriving immigrants were inspected and processed.", "what_zh": "1892年纽约埃利斯岛作为联邦移民检查站开放，抵美移民在此接受检查和办理手续。", "cause_en": "Surging immigration and the federal takeover of immigration inspection required a central gateway.", "cause_zh": "移民激增和联邦接管移民检查需要一个中央门户。", "sig_en": "Ellis Island became the symbol of America as a nation of immigrants — and of the inspections that excluded the deemed unfit.", "sig_zh": "埃利斯岛成为移民之国的象征——也是被认为不合格者遭拒之门的象征。", "exp_en": "The island was a doorway with a gatekeeper: welcome for most, rejection for the deemed unfit.", "exp_zh": "这座岛是带守门人的大门：对多数人欢迎，对被认为不合格者拒绝。", "page": 635, "topic_es": "Ellis Island", "what_es": "Ellis Island de Nueva York abrió en 1892 como la estación federal de inmigración por la que los inmigrantes que llegaban eran inspeccionados y procesados.", "cause_es": "El aumento vertiginoso de la inmigración y la toma federal de la inspección migratoria requirieron una puerta central.", "sig_es": "Ellis Island se convirtió en el símbolo de Estados Unidos como nación de inmigrantes, y de las inspecciones que excluían a los considerados no aptos.", "exp_es": "La isla era una puerta con guardián: bienvenida para la mayoría, rechazo para los considerados no aptos.", "who_es": ["inmigrantes recién llegados"]}, {"id": "p6-042", "period": 6, "topic_en": "Skyscraper / Chicago school", "topic_zh": "摩天大楼/芝加哥学派", "year": 1885, "year_text": "1885", "who": ["Louis Sullivan"], "who_zh": ["路易斯·沙利文"], "what_en": "The first skyscraper was completed in Chicago in 1885. Architect Louis Sullivan and the Chicago school pioneered the steel-frame vertical aesthetic of set-back windows and soaring facades.", "what_zh": "第一座摩天大楼1885年在芝加哥落成。建筑师沙利文和芝加哥学派开创了钢框架的垂直美学：退台式窗户、高耸立面。", "cause_en": "Steel-frame construction and the elevator made tall buildings possible on expensive downtown land.", "cause_zh": "钢框架结构和电梯让在昂贵的市中心土地上建高楼成为可能。", "sig_en": "Skyscrapers became the signature of the industrial metropolis and a symbol of American corporate power.", "sig_zh": "摩天大楼成为工业大都会的标志和美国公司权力的象征。", "exp_en": "Chicago taught the world to build up when there was no room to build out.", "exp_zh": "芝加哥教会世界：无地可扩时，就向上建。", "page": 608, "topic_es": "Rascacielos / escuela de Chicago", "what_es": "El primer rascacielos se completó en Chicago en 1885. El arquitecto Louis Sullivan y la escuela de Chicago fueron pioneros de la estética vertical de estructura de acero, con ventanas retranqueadas y fachadas elevadas.", "cause_es": "La construcción con estructura de acero y el ascensor hicieron posibles edificios altos en el costoso suelo del centro.", "sig_es": "Los rascacielos se convirtieron en la firma de la metrópolis industrial y en símbolo del poder corporativo estadounidense.", "exp_es": "Chicago enseñó al mundo a construir hacia arriba cuando no había espacio para construir hacia afuera.", "who_es": ["Louis Sullivan"]}, {"id": "p6-043", "period": 6, "topic_en": "How the Other Half Lives (Jacob Riis)", "topic_zh": "《另一半人的生活》（雅各布·里斯）", "year": 1890, "year_text": "1890", "who": ["Jacob Riis"], "who_zh": ["雅各布·里斯"], "what_en": "Danish-born reporter Jacob Riis's 1890 book How the Other Half Lives used flash photography to expose New York slum life, shocking middle-class readers with ground-level images of tenement poverty.", "what_zh": "丹麦裔记者里斯1890年出版《另一半人的生活》，用闪光灯摄影揭露纽约贫民窟生活，以底层的公寓贫困影像震惊中产阶级读者。", "cause_en": "Muckraking impulse and new photographic technology made the invisible slums visible.", "cause_zh": "扒粪冲动和新摄影技术让看不见的贫民窟变得可见。", "sig_en": "It built public support for tenement and housing reform, including the Tenement House Law.", "sig_zh": "它赢得了公众对公寓房和住房改革（包括《公寓房法》）的支持。", "exp_en": "Riis made poverty photographic — and therefore undeniable.", "exp_zh": "里斯让贫困有了照片——因而无可否认。", "page": 625, "topic_es": "Cómo vive la otra mitad (Jacob Riis)", "what_es": "El libro de 1890 del reportero danés Jacob Riis, Cómo vive la otra mitad, usó fotografía con flash para exponer la vida en los barrios bajos de Nueva York, conmocionando a lectores de clase media con imágenes directas de la pobreza de las vecindades.", "cause_es": "El impulso muckraker y la nueva tecnología fotográfica hicieron visibles los barrios bajos invisibles.", "sig_es": "Construyó apoyo público para la reforma de vecindades y vivienda, incluida la Ley de Casas de Vecindad.", "exp_es": "Riis hizo fotográfica la pobreza, y por tanto innegable.", "who_es": ["Jacob Riis"], "img": {"file": "img:f2_693", "credit": "图源：Henretta《America's History》第8版 p.625"}}, {"id": "p6-044", "period": 6, "topic_en": "Mann Act", "topic_zh": "《曼恩法》", "year": 1910, "year_text": "1910", "who": ["U.S. Congress"], "who_zh": ["美国国会"], "what_en": "The Mann Act of 1910 prohibited the transportation of prostitutes across state lines, part of a Progressive Era crusade against prostitution and white slavery that closed red-light districts in cities nationwide between 1909 and 1912.", "what_zh": "1910年《曼恩法》禁止跨州运送妓女，是进步时代反卖淫、反白奴 crusade 的一部分；1909至1912年间全国城市红灯区相继被关闭。", "cause_en": "Alarm over white slavery, vice commissions, and machine bosses' payoffs from brothel keepers drove the crusade.", "cause_zh": "对白奴的恐慌、风化委员会以及机器老板从妓院抽成，推动了这场运动。", "sig_en": "It expanded federal police power over morality, though closing brothels worsened conditions for many sex workers.", "sig_zh": "它扩大了联邦在道德领域的警权，但关闭妓院反而恶化了许多性工作者的处境。", "exp_en": "The Mann Act showed progressivism's moralizing edge: reform could also punish.", "exp_zh": "曼恩法显示了进步主义的道德说教一面：改革也会惩罚人。", "page": 627, "topic_es": "Ley Mann", "what_es": "La Ley Mann de 1910 prohibió el transporte de prostitutas a través de las fronteras estatales, parte de una cruzada de la Era Progresista contra la prostitución y la trata de blancas que cerró distritos de tolerancia en ciudades de todo el país entre 1909 y 1912.", "cause_es": "La alarma ante la trata de blancas, las comisiones contra el vicio y los sobornos de los jefes de maquinarias por parte de dueños de burdeles impulsaron la cruzada.", "sig_es": "Expandió el poder policial federal sobre la moral, aunque el cierre de burdeles empeoró las condiciones de muchas trabajadoras sexuales.", "exp_es": "La Ley Mann mostró el filo moralizante del progresismo: la reforma también podía castigar.", "who_es": ["Congreso de EE. UU."], "img": {"file": "img:f2_698", "credit": "图源：Henretta《America's History》第8版 p.627"}}, {"id": "p6-045", "period": 6, "topic_en": "Ragtime", "topic_zh": "拉格泰姆", "year": null, "year_text": "1890s", "who": ["Scott Joplin"], "who_zh": ["斯科特·乔普林"], "what_en": "Ragtime, introduced to national audiences at the 1893 Chicago World's Fair and popularized by composers like Scott Joplin, became wildly popular among audiences of all classes and races.", "what_zh": "拉格泰姆在1893年芝加哥哥伦比亚博览会上首次介绍给全国观众，经乔普林等作曲家推广，风靡各阶级各族裔听众。", "cause_en": "Black musical innovation met the new world of mass urban entertainment.", "cause_zh": "黑人音乐创新遇上了大众城市娱乐的新世界。", "sig_en": "It marked the rise of a distinctively American popular music rooted in African American culture.", "sig_zh": "它标志着植根于非裔美国人文化的独特美国流行音乐的兴起。", "exp_en": "Ragtime was syncopation as democracy: everybody's music, from everybody's piano.", "exp_zh": "拉格泰姆是切分音的民主：人人的音乐，出自人人的钢琴。", "page": 617, "topic_es": "Ragtime", "what_es": "El ragtime, presentado a audiencias nacionales en la Feria Mundial de Chicago de 1893 y popularizado por compositores como Scott Joplin, se volvió enormemente popular entre audiencias de todas las clases y razas.", "cause_es": "La innovación musical negra se encontró con el nuevo mundo del entretenimiento urbano masivo.", "sig_es": "Marcó el surgimiento de una música popular distintivamente estadounidense enraizada en la cultura afroamericana.", "exp_es": "El ragtime fue la sincopación como democracia: música de todos, desde el piano de todos.", "who_es": ["Scott Joplin"], "img": {"file": "img:f2_671", "credit": "图源：Henretta《America's History》第8版 p.617"}}, {"id": "p6-046", "period": 6, "topic_en": "Pendleton Act", "topic_zh": "《彭德尔顿法》", "year": 1883, "year_text": "1883", "who": ["U.S. Congress"], "who_zh": ["美国国会"], "what_en": "After President Garfield's assassination, Congress passed the Pendleton Act (1883), establishing a nonpartisan Civil Service Commission to fill federal jobs by examination. Initially covering 10 percent of federal jobs, it was extended to most federal positions by the 1910s.", "what_zh": "加菲尔德总统遇刺后，国会通过1883年《彭德尔顿法》，设立无党派文官委员会，以考试录用联邦雇员。起初只覆盖10%的联邦职位，到1910年代扩大到大多数职位。", "cause_en": "Outrage at the spoils system after a disappointed office-seeker assassinated Garfield in 1881 demanded reform of patronage hiring.", "cause_zh": "1881年求官不成的刺客杀害加菲尔德，举国对分赃制度的愤怒要求改革恩赐制用人。", "sig_en": "It began the professionalization of the federal bureaucracy and weakened party machines' patronage power.", "sig_zh": "它开启了联邦官僚的专业化，削弱了政党机器的恩赐权力。", "exp_en": "The Pendleton Act replaced who you know with what you know — at least for federal jobs.", "exp_zh": "彭德尔顿法用人唯亲换成了用人唯贤——至少在联邦职位上。", "page": 638, "topic_es": "Ley Pendleton", "what_es": "Tras el asesinato del presidente Garfield, el Congreso aprobó la Ley Pendleton (1883), estableciendo una Comisión de Servicio Civil no partidista para cubrir empleos federales por examen. Inicialmente cubría el 10 por ciento de los empleos federales, y se extendió a la mayoría de los puestos federales para la década de 1910.", "cause_es": "La indignación ante el sistema de botín después de que un aspirante decepcionado a un cargo asesinara a Garfield en 1881 exigió reformar la contratación por clientelismo.", "sig_es": "Inició la profesionalización de la burocracia federal y debilitó el poder clientelar de las maquinarias partidistas.", "exp_es": "La Ley Pendleton reemplazó el a quién conoces por el qué sabes, al menos para los empleos federales.", "who_es": ["Congreso de EE. UU."]}, {"id": "p6-047", "period": 6, "topic_en": "Sherman Antitrust Act", "topic_zh": "《谢尔曼反托拉斯法》", "year": 1890, "year_text": "1890", "who": ["U.S. Congress"], "who_zh": ["美国国会"], "what_en": "The Sherman Antitrust Act (1890) was the first federal attempt to forbid any combination, in the form of trust or otherwise, or conspiracy, in restraint of trade, passed amid growing public outrage over trusts.", "what_zh": "1890年《谢尔曼反托拉斯法》是联邦首次尝试禁止任何托拉斯形式或其他形式的联合、或限制贸易的共谋，在公众对托拉斯的愤怒中通过。", "cause_en": "Farmer-labor protest against monopolies like Standard Oil forced Republicans to act after they won control of Congress and the White House in 1888.", "cause_zh": "农民和劳工对标准石油等垄断的抗议，迫使1888年掌控国会和白宫的共和党采取行动。", "sig_en": "Though difficult to enforce and soon weakened by the Supreme Court, it became the legal foundation for later trust-busting.", "sig_zh": "虽难执行、很快被最高法院削弱，它成为后来反托拉斯的法律基础。", "exp_en": "The Sherman Act declared war on the trusts — then left the generals without an army.", "exp_zh": "谢尔曼法向托拉斯宣战——却没给将军们配军队。", "page": 642, "topic_es": "Sherman Antitrust Act", "what_es": "La Sherman Antitrust Act (1890) fue el primer intento federal de prohibir toda combinación, en forma de trust o de otro modo, o conspiración, que restringiera el comercio, aprobada en medio de la creciente indignación pública contra los trusts.", "cause_es": "La protesta agrario-obrera contra monopolios como Standard Oil obligó a los republicanos a actuar tras ganar el control del Congreso y la Casa Blanca en 1888.", "sig_es": "Aunque difícil de aplicar y pronto debilitada por la Corte Suprema, se convirtió en la base legal para la posterior lucha contra los trusts.", "exp_es": "La Sherman Act declaró la guerra a los trusts, y luego dejó a los generales sin ejército.", "who_es": ["Congreso de EE. UU."], "img": {"file": "img:f2_736", "credit": "图源：Henretta《America's History》第8版 p.642"}}, {"id": "p6-048", "period": 6, "topic_en": "People's Party / Omaha Platform", "topic_zh": "人民党/奥马哈纲领", "year": 1892, "year_text": "July 1892", "who": ["James B. Weaver"], "who_zh": ["詹姆斯·B·韦弗"], "what_en": "In July 1892 delegates met at Omaha, Nebraska, and created the national People's Party, nominating former Union general James B. Weaver for president. The Populists won a million votes and carried four western states. Their Omaha Platform declared that the power of government — in other words, of the people — should be expanded as rapidly and as far as the good sense of an intelligent people and the teachings of experience shall justify.", "what_zh": "1892年7月代表们在内布拉斯加奥马哈创建全国人民党，提名前联邦将军韦弗竞选总统。民粹党人赢得一百万选票、拿下四个西部州。奥马哈纲领宣称：政府的权力——换言之人民的权力——应当随着明智人民的良知和经验的教导而尽可能迅速、尽可能广泛地扩张。", "cause_en": "Farmers' Alliance and Knights of Labor veterans believed the mainstream parties served corporations, not ordinary Americans, after politicians treated Alliance pleas with contempt.", "cause_zh": "农民同盟和劳工骑士团的老兵认为主流政党服务公司而非普通美国人——政客们曾对同盟的诉求嗤之以鼻。", "sig_en": "Populism forced the major parties to address reform; its ideas flowed into progressivism and, decades later, the New Deal.", "sig_zh": "民粹主义迫使大党回应改革，其思想汇入进步主义，数十年后又汇入新政。", "exp_en": "The Populists lost the election but won the argument — within a generation, their platform was the law of the land.", "exp_zh": "民粹党人输了选举却赢了辩论——一代人之内，他们的纲领成了国法。", "page": 643, "src": {"text": "We believe that the power of government — in other words, of the people — should be expanded as rapidly and as far as the good sense of an intelligent people and the teachings of experience shall justify.", "attr": "Omaha Platform (1892)"}, "topic_es": "Partido del Pueblo / Plataforma de Omaha", "what_es": "En julio de 1892 delegados se reunieron en Omaha, Nebraska, y crearon el Partido del Pueblo nacional, nominando al ex general de la Unión James B. Weaver para presidente. Los populistas ganaron un millón de votos y se llevaron cuatro estados del oeste. Su Plataforma de Omaha declaró que el poder del gobierno, en otras palabras, del pueblo, debería expandirse tan rápida y ampliamente como lo justificaran el buen juicio de un pueblo inteligente y las enseñanzas de la experiencia.", "cause_es": "Veteranos de la Alianza de Agricultores y los Caballeros del Trabajo creían que los partidos tradicionales servían a las corporaciones, no a los estadounidenses comunes, después de que los políticos trataran con desprecio las súplicas de la Alianza.", "sig_es": "El populismo obligó a los partidos mayoritarios a abordar la reforma; sus ideas fluyeron hacia el progresismo y, décadas después, hacia el New Deal.", "exp_es": "Los populistas perdieron la elección pero ganaron el argumento: en una generación, su plataforma era la ley del país.", "who_es": ["James B. Weaver"], "img": {"file": "img:f2_740", "credit": "图源：Henretta《America's History》第8版 p.643"}}, {"id": "p6-049", "period": 6, "topic_en": "Free silver / William Jennings Bryan", "topic_zh": "自由铸银/威廉·詹宁斯·布莱恩", "year": 1896, "year_text": "1896", "who": ["William Jennings Bryan", "William McKinley"], "who_zh": ["威廉·詹宁斯·布莱恩", "威廉·麦金利"], "what_en": "Free-silver advocates wanted the Mint to coin silver as well as gold to expand the money supply. In 1896 Democrats nominated young Nebraska congressman William Jennings Bryan, who defended farmers and attacked the gold standard: burn down your cities and leave our farms, and your cities will spring up again as if by magic; but destroy our farms and the grass will grow in the streets.", "what_zh": "自由铸银派主张铸币局除黄金外也铸银币以扩大货币供应。1896年民主党提名年轻的内布拉斯加众议员布莱恩，他捍卫农民、攻击金本位：烧掉你们的城市留下我们的农场，城市会如魔法般重生；但摧毁我们的农场，街道上将长满青草。", "cause_en": "Deflation and the depression of the 1890s crushed debt-burdened farmers while President Cleveland clung to the gold standard.", "cause_zh": "通缩和1890年代大萧条压垮了负债农民，而克利夫兰总统死守金本位。", "sig_en": "McKinley defeated Bryan (271 to 176 electoral votes), crushing Populism as a separate party but making the Democrats the party of reform.", "sig_zh": "麦金利击败布莱恩（选举人票271比176），民粹主义作为独立政党被粉碎，但民主党成了改革之党。", "exp_en": "Free silver was really about who controls money: the bankers or the people.", "exp_zh": "自由铸银真正的问题是货币由谁控制：银行家还是人民。", "page": 645, "why_term": "free silver", "why_term_q": "1896年布莱恩主张扩大货币供应的货币政策叫 ______。", "topic_es": "Plata libre / William Jennings Bryan", "what_es": "Los defensores de la plata libre querían que la Casa de la Moneda acuñara plata además de oro para expandir la oferta monetaria. En 1896 los demócratas nominaron al joven congresista de Nebraska William Jennings Bryan, quien defendió a los agricultores y atacó el patrón oro: quemen sus ciudades y dejen nuestras granjas, y sus ciudades resurgirán como por arte de magia; pero destruyan nuestras granjas y la hierba crecerá en las calles.", "cause_es": "La deflación y la depresión de la década de 1890 aplastaron a agricultores endeudados mientras el presidente Cleveland se aferraba al patrón oro.", "sig_es": "McKinley derrotó a Bryan (271 contra 176 votos electorales), aplastando al populismo como partido separado pero convirtiendo a los demócratas en el partido de la reforma.", "exp_es": "La plata libre trataba realmente de quién controla el dinero: los banqueros o el pueblo.", "who_es": ["William Jennings Bryan", "William McKinley"], "why_term_q_es": "La política monetaria que Bryan defendió en 1896 para expandir la oferta monetaria se llamaba ______."}, {"id": "p6-050", "period": 6, "topic_en": "Coxey's Army", "topic_zh": "考克西大军", "year": 1894, "year_text": "summer 1894", "who": ["Jacob Coxey"], "who_zh": ["雅各布·考克西"], "what_en": "In the summer of 1894 Ohio businessman Jacob Coxey organized hundreds of jobless men — nicknamed Coxey's Army — to march peacefully to Washington demanding the government hire the unemployed to fix America's roads. Coxey was jailed for trespassing on the Capitol grass, some men ended up in Maryland chain gangs, and the rest went home hungry.", "what_zh": "1894年夏，俄亥俄商人考克西组织数百失业者——号称考克西大军——和平进军华盛顿，要求政府雇失业者修路。考克西因擅闯国会草坪入狱，有人被送进马里兰的苦役队，其余人饿着肚子回家。", "cause_en": "Mass unemployment in the depression of the 1890s left workers with no relief and no voice.", "cause_zh": "1890年代大萧条的普遍失业让工人既无救济也无话语权。", "sig_en": "Though a failure, its demand for public employment of the jobless would become central to the New Deal in the 1930s.", "sig_zh": "虽以失败告终，其由政府雇佣失业者的主张在1930年代成为新政的核心。", "exp_en": "Coxey's Army was laughed at in 1894 — and legislated in 1933.", "exp_zh": "考克西大军1894年被人嘲笑——1933年却被写进法律。", "page": 645, "topic_es": "El ejército de Coxey", "what_es": "En el verano de 1894 el empresario de Ohio Jacob Coxey organizó a cientos de desempleados, apodados el ejército de Coxey, para marchar pacíficamente a Washington exigiendo que el gobierno contratara a los desempleados para arreglar los caminos de Estados Unidos. Coxey fue encarcelado por invadir el césped del Capitolio, algunos hombres terminaron en cuadrillas de presos de Maryland y el resto volvió a casa hambriento.", "cause_es": "El desempleo masivo en la depresión de la década de 1890 dejó a los obreros sin alivio y sin voz.", "sig_es": "Aunque fue un fracaso, su demanda de empleo público para los desempleados se volvería central para el New Deal en la década de 1930.", "exp_es": "Del ejército de Coxey se rieron en 1894, y se legisló en 1933.", "who_es": ["Jacob Coxey"]}, {"id": "p6-051", "period": 6, "topic_en": "Williams v. Mississippi", "topic_zh": "威廉斯诉密西西比案", "year": 1898, "year_text": "1898", "who": ["U.S. Supreme Court"], "who_zh": ["美国最高法院"], "what_en": "In Williams v. Mississippi (1898) the Supreme Court allowed poll taxes and literacy tests for voters, giving constitutional cover to the disenfranchisement of Black Southerners.", "what_zh": "1898年威廉斯诉密西西比案中，最高法院允许以人头税和文化测试限制选民，给剥夺南方黑人选举权披上宪法外衣。", "cause_en": "Southern Democrats sought to eliminate Black voting after the Populist threat showed the danger of biracial farmer-labor coalitions.", "cause_zh": "民粹主义的威胁显示了黑白农工联盟的危险，南方民主党决心消灭黑人选票。", "sig_en": "It entrenched the Solid South and one-party Democratic rule for decades.", "sig_zh": "它巩固了坚固的南方，使民主党一党统治延续数十年。", "exp_en": "Williams v. Mississippi was Plessy's twin: one segregated the ballot box, the other the railroad car.", "exp_zh": "威廉斯案是普莱西案的孪生兄弟：一个隔离票箱，一个隔离车厢。", "page": 645, "topic_es": "Williams contra Misisipi", "what_es": "En Williams contra Misisipi (1898) la Corte Suprema permitió impuestos electorales y pruebas de alfabetización para los votantes, dando cobertura constitucional a la privación del voto de los negros del Sur.", "cause_es": "Los demócratas del Sur buscaron eliminar el voto negro después de que la amenaza populista mostrara el peligro de las coaliciones birraciales de agricultores y obreros.", "sig_es": "Afianzó el Sur sólido y el gobierno demócrata de partido único durante décadas.", "exp_es": "Williams contra Misisipi fue el gemelo de Plessy: uno segregó la urna, el otro el vagón.", "who_es": ["Corte Suprema de EE. UU."]}, {"id": "p6-052", "period": 6, "topic_en": "Lochner v. New York", "topic_zh": "洛克纳诉纽约州案", "year": 1905, "year_text": "1905", "who": ["U.S. Supreme Court"], "who_zh": ["美国最高法院"], "what_en": "In Lochner v. New York (1905) the Supreme Court told New York State it could not limit bakers' workday to ten hours, ruling it violated bakers' rights to make contracts. Judges found support in the Fourteenth Amendment's due process clause — intended to protect former slaves — now used to shield contract rights.", "what_zh": "1905年洛克纳诉纽约州案中，最高法院裁定纽约州不得把面包师工时限制为十小时，认为这侵犯了面包师的契约权。法官的依据是第十四条修正案的正当程序条款——本为保护前奴隶而设，如今被用来保护契约权。", "cause_en": "Courts hostile to labor regulation used liberty of contract to strike down progressive reforms.", "cause_zh": "敌视劳工管制的法院用契约自由来推翻进步主义改革。", "sig_en": "Lochner became the symbol of conservative judicial obstruction of progressive reform, an era of jurisprudence that lasted into the 1930s.", "sig_zh": "洛克纳案成为保守司法阻挠进步改革的象征，这一司法时代延续到1930年代。", "exp_en": "Lochner turned the amendment meant to free the slaves into a shield for the sweatshop.", "exp_zh": "洛克纳把本为解放奴隶的修正案变成了血汗工厂的盾牌。", "page": 649, "topic_es": "Lochner contra Nueva York", "what_es": "En Lochner contra Nueva York (1905) la Corte Suprema dijo al estado de Nueva York que no podía limitar a diez horas la jornada de los panaderos, dictaminando que violaba el derecho de los panaderos a contratar. Los jueces encontraron apoyo en la cláusula del debido proceso de la Decimocuarta Enmienda, pensada para proteger a ex esclavos y ahora usada para blindar derechos contractuales.", "cause_es": "Tribunales hostiles a la regulación laboral usaron la libertad de contrato para anular reformas progresistas.", "sig_es": "Lochner se convirtió en el símbolo de la obstrucción judicial conservadora a la reforma progresista, una era jurisprudencial que duró hasta la década de 1930.", "exp_es": "Lochner convirtió la enmienda pensada para liberar a los esclavos en un escudo para el taller clandestino.", "who_es": ["Corte Suprema de EE. UU."], "img": {"file": "img:f2_763", "credit": "图源：Henretta《America's History》第8版 p.649"}}, {"id": "p6-053", "period": 6, "topic_en": "Muller v. Oregon", "topic_zh": "穆勒诉俄勒冈州案", "year": 1908, "year_text": "1908", "who": ["U.S. Supreme Court", "National Consumers' League"], "who_zh": ["美国最高法院", "全国消费者联盟"], "what_en": "In Muller v. Oregon (1908) the Supreme Court upheld an Oregon law limiting women's work hours, permitting state regulation of women's working hours — a major triumph for those seeking to protect working-class women.", "what_zh": "1908年穆勒诉俄勒冈州案中，最高法院维持俄勒冈州限制妇女工时的法律，允许州管制妇女工作时间——这是保护职业妇女者的重大胜利。", "cause_en": "Reformers led by the National Consumers' League documented brutal conditions for women workers and pressed for protective laws.", "cause_zh": "全国消费者联盟领导的改革者记录了女工的恶劣处境，推动保护性立法。", "sig_en": "A landmark victory for protective labor legislation, though it rested on arguments about women's special vulnerability rather than workers' rights as such.", "sig_zh": "这是保护性劳工立法的里程碑胜利，尽管其论证基于妇女的特殊脆弱而非工人权利本身。", "exp_en": "Muller won protection for women by arguing they needed it — a victory with strings attached.", "exp_zh": "穆勒案以妇女需要保护为由赢得保护——一场附带条件的胜利。", "page": 652, "topic_es": "Muller contra Oregón", "what_es": "En Muller contra Oregón (1908) la Corte Suprema confirmó una ley de Oregón que limitaba las horas de trabajo de las mujeres, permitiendo la regulación estatal de la jornada laboral femenina: un gran triunfo para quienes buscaban proteger a las obreras.", "cause_es": "Reformistas liderados por la Liga Nacional de Consumidores documentaron las brutales condiciones de las obreras e impulsaron leyes protectoras.", "sig_es": "Una victoria histórica para la legislación laboral protectora, aunque descansaba en argumentos sobre la especial vulnerabilidad de las mujeres más que en los derechos de los trabajadores como tales.", "exp_es": "Muller ganó protección para las mujeres argumentando que la necesitaban: una victoria con condiciones.", "who_es": ["Corte Suprema de EE. UU.", "Liga Nacional de Consumidores"]}, {"id": "p6-054", "period": 6, "topic_en": "Wisconsin Idea", "topic_zh": "威斯康星理念", "year": null, "year_text": "early 1900s", "who": ["Robert La Follette"], "who_zh": ["罗伯特·拉福莱特"], "what_en": "Wisconsin governor Robert La Follette's Wisconsin Idea won battles to restrict lobbying and give citizens the recall — voting to remove unpopular politicians from office — and the referendum — voting directly on a proposed law. In the U.S. Senate he pushed increasingly aggressive measures to protect workers and rein in corporate power.", "what_zh": "威斯康星州长拉福莱特的威斯康星理念赢得限制游说、赋予公民罢免权（投票罢免不受欢迎的官员）和创制复决权（直接对法案投票）的斗争。进入联邦参议院后，他推动更激进的保护工人、约束公司的措施。", "cause_en": "Progressive anger at corporate domination of state legislatures demanded new democratic tools.", "cause_zh": "进步主义者对公司控制州议会的愤怒要求新的民主工具。", "sig_en": "Wisconsin became the laboratory of democracy whose reforms — recall, referendum, direct primary — were copied nationwide.", "sig_zh": "威斯康星成为民主实验室，其罢免、复决、直接初选等改革被全国效仿。", "exp_en": "The Wisconsin Idea said experts and voters together could out-govern the bosses.", "exp_zh": "威斯康星理念认为：专家加选民，能比老板们治理得更好。", "page": 652, "topic_es": "Idea de Wisconsin", "what_es": "La Idea de Wisconsin del gobernador Robert La Follette ganó batallas para restringir el cabildeo y dar a los ciudadanos la revocación — votar para destituir a políticos impopulares — y el referéndum — votar directamente sobre una ley propuesta. En el Senado de EE. UU. impulsó medidas cada vez más agresivas para proteger a los obreros y frenar el poder corporativo.", "cause_es": "La ira progresista ante la dominación corporativa de las legislaturas estatales exigía nuevas herramientas democráticas.", "sig_es": "Wisconsin se convirtió en el laboratorio de la democracia cuyas reformas — revocación, referéndum, primarias directas — se copiaron en todo el país.", "exp_es": "La Idea de Wisconsin decía que expertos y votantes juntos podían gobernar mejor que los caciques.", "who_es": ["Robert La Follette"]}, {"id": "p6-055", "period": 6, "topic_en": "Niagara Principles / NAACP", "topic_zh": "尼亚加拉原则/全国有色人种协进会", "year": 1905, "year_text": "1905 (Niagara); 1909 (NAACP)", "who": ["W. E. B. Du Bois", "William Monroe Trotter"], "who_zh": ["W·E·B·杜波依斯", "威廉·门罗·特罗特"], "what_en": "In 1905 Du Bois and Trotter met at Niagara Falls — on the Canadian side, because no U.S. hotel would admit Blacks — and issued the Niagara Principles: full voting rights, an end to segregation, equal treatment in justice, and equal opportunity in education, jobs, health care, and military service. The movement led to the creation of the NAACP in 1909, whose journal The Crisis Du Bois edited.", "what_zh": "1905年杜波依斯和特罗特在尼亚加拉瀑布开会——选在加拿大一侧，因为美国旅馆不接待黑人——发表尼亚加拉原则：完全投票权、终结隔离、司法平等待遇、教育就业医疗服役机会平等。该运动促成1909年全国有色人种协进会成立，杜波依斯主编其刊物《危机》。", "cause_en": "Du Bois declared Washington's policy of compromise a failure and called on the talented tenth of educated Blacks to demand full equality.", "cause_zh": "杜波依斯宣称华盛顿的妥协政策失败，号召黑人中受过教育的十分之一精英要求完全平等。", "sig_en": "It founded the modern civil-rights movement's leading organization, guided by uncompromising demand for full equality.", "sig_zh": "它创立了现代民权运动的主要组织，以毫不妥协的完全平等诉求为指南。", "exp_en": "The Niagara movement traded the Atlanta Compromise's patience for a demand: equality now.", "exp_zh": "尼亚加拉运动用亚特兰大妥协的耐心换来一声要求：现在就要平等。", "page": 655, "why_term": "talented tenth", "why_term_q": "杜波依斯号召领导黑人抗争的受过教育的精英阶层叫 ______。", "topic_es": "Principios de Niágara / NAACP", "what_es": "En 1905 Du Bois y Trotter se reunieron en las cataratas del Niágara — del lado canadiense, porque ningún hotel estadounidense admitía negros — y emitieron los Principios de Niágara: pleno derecho al voto, fin de la segregación, igualdad de trato ante la justicia e igualdad de oportunidades en educación, empleos, salud y servicio militar. El movimiento llevó a la creación de la NAACP en 1909, cuya revista The Crisis editó Du Bois.", "cause_es": "Du Bois declaró fracasada la política de compromiso de Washington y llamó al décimo talentoso de negros educados a exigir plena igualdad.", "sig_es": "Fundó la organización líder del movimiento moderno por los derechos civiles, guiada por la exigencia intransigente de plena igualdad.", "exp_es": "El movimiento de Niágara cambió la paciencia del Compromiso de Atlanta por una exigencia: igualdad ahora.", "who_es": ["W. E. B. Du Bois", "William Monroe Trotter"], "why_term_q_es": "La élite educada que Du Bois llamó a liderar la lucha negra se llamaba ______.", "img": {"file": "img:f2_777", "credit": "图源：Henretta《America's History》第8版 p.655"}}, {"id": "p6-056", "period": 6, "topic_en": "Industrial Workers of the World", "topic_zh": "世界产业工人工会", "year": 1905, "year_text": "1905", "who": ["IWW organizers"], "who_zh": ["IWW组织者"], "what_en": "Founded in 1905, the Industrial Workers of the World (IWW) was a radical union that organized unskilled workers across industries and led high-profile strikes, alarming employers and the government.", "what_zh": "1905年成立的世界产业工人工会是激进工会，跨行业组织非熟练工人，领导了引人注目的罢工，让雇主和政府警觉。", "cause_en": "The AFL organized only skilled workers, leaving the unskilled — and the appeal of revolutionary industrial unionism — to the IWW.", "cause_zh": "AFL只组织熟练工人，非熟练工人和革命性产业工会主义的诉求留给了IWW。", "sig_en": "It kept the most militant edge of American labor alive in the Progressive Era and forced labor issues onto the national agenda.", "sig_zh": "它让美国劳工最激进的一翼在进步时代存活，并把劳工问题推上全国议程。", "exp_en": "The Wobblies organized the workers the AFL would not touch — and paid for it.", "exp_zh": "世界产业工人组织的正是AFL不碰的工人——并为此付出代价。", "page": 655, "topic_es": "Trabajadores Industriales del Mundo", "what_es": "Fundada en 1905, los Trabajadores Industriales del Mundo (IWW) fue un sindicato radical que organizó a obreros no calificados de todas las industrias y lideró huelgas de alto perfil, alarmando a empleadores y al gobierno.", "cause_es": "La AFL solo organizaba a obreros calificados, dejando a los no calificados — y el atractivo del sindicalismo industrial revolucionario — al IWW.", "sig_es": "Mantuvo vivo el filo más militante del trabajo estadounidense en la Era Progresista y forzó los temas laborales a la agenda nacional.", "exp_es": "Los wobblies organizaron a los obreros que la AFL no quiso tocar, y lo pagaron.", "who_es": ["Organizadores del IWW"], "img": {"file": "img:f2_777", "credit": "图源：Henretta《America's History》第8版 p.655"}}, {"id": "p6-057", "period": 6, "topic_en": "Socialist Party of America (Eugene V. Debs)", "topic_zh": "美国社会党（尤金·V·德布斯）", "year": 1901, "year_text": "1901", "who": ["Eugene V. Debs"], "who_zh": ["尤金·V·德布斯"], "what_en": "In 1901 Eugene Debs founded the Socialist Party of America, giving political form to American socialism and becoming its perennial presidential candidate.", "what_zh": "1901年德布斯创办美国社会党，使美国社会主义有了政治形态，他本人成为该党常年的总统候选人。", "cause_en": "Disillusionment with both major parties and the appeal of socialism to workers facing industrial exploitation fueled its rise.", "cause_zh": "对两大党的幻灭和社会主义对受工业剥削工人的吸引力推动了它的兴起。", "sig_en": "The party peaked in the 1910s, and conservative alarms over it launched America's first Red Scare.", "sig_zh": "该党在1910年代达到顶峰，保守派对它的恐慌引发了美国第一次红色恐慌。", "exp_en": "Debs made socialism speak American — and a million voters listened.", "exp_zh": "德布斯让社会主义说美国话——一百万选民听进去了。", "page": 657, "topic_es": "Partido Socialista de Estados Unidos (Eugene V. Debs)", "what_es": "En 1901 Eugene Debs fundó el Partido Socialista de Estados Unidos, dando forma política al socialismo estadounidense y convirtiéndose en su perenne candidato presidencial.", "cause_es": "La desilusión con ambos partidos mayoritarios y el atractivo del socialismo para obreros que enfrentaban la explotación industrial alimentaron su ascenso.", "sig_es": "El partido alcanzó su apogeo en la década de 1910, y las alarmas conservadoras ante él lanzaron el primer Temor Rojo de Estados Unidos.", "exp_es": "Debs hizo que el socialismo hablara estadounidense, y un millón de votantes escucharon.", "who_es": ["Eugene V. Debs"], "img": {"file": "img:f2_782", "credit": "图源：Henretta《America's History》第8版 p.657"}}, {"id": "p6-058", "period": 6, "topic_en": "New Nationalism", "topic_zh": "新国家主义", "year": 1910, "year_text": "August 1910", "who": ["Theodore Roosevelt"], "who_zh": ["西奥多·罗斯福"], "what_en": "In an August 1910 speech at Osawatomie, Kansas, Theodore Roosevelt called for a New Nationalism: in modern America, private property had to be controlled to whatever degree the public welfare may require it. He proposed a federal child labor law, more recognition of labor rights, and a national minimum wage for women.", "what_zh": "1910年8月罗斯福在堪萨斯奥萨瓦托米演说中提出新国家主义：在现代美国，私有财产必须在公共福利要求的任何程度上受到控制。他主张联邦童工法、更多劳工权利和全国妇女最低工资。", "cause_en": "Back from an African safari, Roosevelt found President Taft compromising with conservatives and wanted a bolder progressive program.", "cause_zh": "非洲狩猎归来后，罗斯福发现塔夫脱向保守派妥协，想要更大胆的进步主义纲领。", "sig_en": "It set the platform for his 1912 Bull Moose run and pushed progressivism leftward toward an active federal government.", "sig_zh": "它成为他1912年公麋党竞选的纲领，把进步主义推向更积极的联邦政府方向。", "exp_en": "The New Nationalism said property rights end where the public welfare begins.", "exp_zh": "新国家主义宣称：财产权止于公共福利始处。", "page": 656, "src": {"text": "In modern America, private property had to be controlled to whatever degree the public welfare may require it.", "attr": "Theodore Roosevelt, New Nationalism speech, Osawatomie, Kansas (August 1910)"}, "topic_es": "Nuevo Nacionalismo", "what_es": "En un discurso de agosto de 1910 en Osawatomie, Kansas, Theodore Roosevelt llamó a un Nuevo Nacionalismo: en la Estados Unidos moderna, la propiedad privada debía controlarse en la medida que el bienestar público lo requiriera. Propuso una ley federal de trabajo infantil, mayor reconocimiento de los derechos laborales y un salario mínimo nacional para las mujeres.", "cause_es": "De regreso de un safari africano, Roosevelt encontró al presidente Taft transigiendo con los conservadores y quiso un programa progresista más audaz.", "sig_es": "Fijó la plataforma para su candidatura del Bull Moose en 1912 e impulsó el progresismo hacia la izquierda, hacia un gobierno federal activo.", "exp_es": "El Nuevo Nacionalismo decía que los derechos de propiedad terminan donde empieza el bienestar público.", "who_es": ["Theodore Roosevelt"], "img": {"file": "img:f2_779", "credit": "图源：Henretta《America's History》第8版 p.656"}}, {"id": "p6-059", "period": 6, "topic_en": "Federal Reserve Act", "topic_zh": "《联邦储备法》", "year": 1913, "year_text": "1913", "who": ["U.S. Congress", "Woodrow Wilson"], "who_zh": ["美国国会", "伍德罗·威尔逊"], "what_en": "The Federal Reserve Act (1913) gave the nation a banking system more resistant to crises: twelve district reserve banks funded and controlled by their member banks, a central Federal Reserve Board to impose regulation, and power to issue currency and set the interest rate district banks charged their members.", "what_zh": "1913年《联邦储备法》给了美国一个更能抵御危机的银行体系：十二家由成员银行出资和控制的地区储备银行、实施监管的中央联邦储备委员会，以及发行货币、设定地区银行对成员利率的权力。", "cause_en": "In the United States the great private banks of New York assumed the central-bank role; when the Knickerbocker Trust Company failed in 1907, precipitating a panic, the entire system nearly collapsed.", "cause_zh": "美国由纽约大私人银行承担中央银行职能；1907年尼克伯克信托公司倒闭引发恐慌，整个体系几乎崩溃。", "sig_en": "It strengthened the banking system, modestly discouraged risky Wall Street speculation, and created America's modern central-banking framework.", "sig_zh": "它强化了银行体系，适度抑制了华尔街的高风险投机，建立了美国现代中央银行框架。", "exp_en": "The Fed was progressivism's answer to the bankers' panic: public control of the money power.", "exp_zh": "美联储是进步主义对银行家恐慌的回答：货币权力归公共控制。", "page": 662, "topic_es": "Ley de la Reserva Federal", "what_es": "La Ley de la Reserva Federal (1913) dio a la nación un sistema bancario más resistente a las crisis: doce bancos de reserva de distrito financiados y controlados por sus bancos miembros, una Junta de la Reserva Federal central para imponer regulación, y poder para emitir moneda y fijar la tasa de interés que los bancos de distrito cobraban a sus miembros.", "cause_es": "En Estados Unidos los grandes bancos privados de Nueva York asumían el rol de banco central; cuando la Knickerbocker Trust Company quebró en 1907, precipitando un pánico, todo el sistema casi colapsó.", "sig_es": "Fortaleció el sistema bancario, desalentó modestamente la especulación riesgosa de Wall Street y creó el marco moderno de banca central de Estados Unidos.", "exp_es": "La Fed fue la respuesta del progresismo al pánico de los banqueros: control público del poder monetario.", "who_es": ["Congreso de EE. UU.", "Woodrow Wilson"]}, {"id": "p6-060", "period": 6, "topic_en": "Clayton Antitrust Act", "topic_zh": "《克莱顿反托拉斯法》", "year": 1914, "year_text": "1914", "who": ["U.S. Congress"], "who_zh": ["美国国会"], "what_en": "The Clayton Antitrust Act (1914) amended the Sherman Act, defining illegal practices by whether an action substantially lessened competition. The new Federal Trade Commission received broad powers to investigate companies and issue cease and desist orders against anticompetitive practices.", "what_zh": "1914年《克莱顿反托拉斯法》修订谢尔曼法，以行为是否实质性削弱竞争来界定违法。新设的联邦贸易委员会获得广泛权力，可调查公司并对反竞争行为发布停止令。", "cause_en": "The Sherman Act had proved difficult to enforce and had been weakened by the courts, so progressives demanded sharper tools.", "cause_zh": "谢尔曼法难执行又被法院削弱，进步主义者要求更锋利的工具。", "sig_en": "It strengthened antitrust enforcement and gave regulators flexible, ongoing power over corporate behavior.", "sig_zh": "它强化了反托拉斯执法，赋予监管者对公司行为灵活持续的权力。", "exp_en": "If Sherman was a declaration of war, Clayton was the field manual.", "exp_zh": "如果说谢尔曼法是宣战书，克莱顿法就是作战手册。", "page": 662, "topic_es": "Clayton Antitrust Act", "what_es": "La Clayton Antitrust Act (1914) enmendó la Sherman Act, definiendo las prácticas ilegales según si una acción reducía sustancialmente la competencia. La nueva Comisión Federal de Comercio recibió amplios poderes para investigar compañías y emitir órdenes de cese y desistimiento contra prácticas anticompetitivas.", "cause_es": "La Sherman Act había resultado difícil de aplicar y había sido debilitada por los tribunales, así que los progresistas exigieron herramientas más afiladas.", "sig_es": "Fortaleció la aplicación antimonopolista y dio a los reguladores un poder flexible y continuo sobre la conducta corporativa.", "exp_es": "Si Sherman fue una declaración de guerra, Clayton fue el manual de campaña.", "who_es": ["Congreso de EE. UU."]}];